style.css:
@-moz-document domain("stackoverflow.com"), domain("superuser.com"), domain("serverfault.com"), domain("askubuntu.com"), domain("mathoverflow.net"), domain("stackexchange.com"), domain("stackapps.com") {
/* ============================================================
     StackExchange Dark
     ------------------------------------------------------------
     The whole network (Stack Overflow, Super User, Server Fault,
     Ask Ubuntu, MathOverflow, and every *.stackexchange.com Q&A
     site) shares ONE frontend — the "Stacks" design system on a
     light "unified-theme" body. The native dark theme is a
     logged-in-only account preference, so anonymous visitors
     (most of the search traffic) only ever see the light site.
     This theme reskins that shared frontend for everyone.

     Colors are compiled literal hex on stable Stacks classes
     (.s-prose, .s-card, .s-input, .s-tag, .s-code-block,
     .s-sidebarwidget, #sidebar, #left-sidebar, .comment, .vote,
     .accepted-answer, .hljs-* syntax tokens). No hashed/obfuscated
     class names are used.

     Stacks DOES expose custom properties, in two layers, and both
     matter here:
       - a global palette on :root (--black-050 … --black-600,
         --bc-light, --white). We deliberately do NOT remap these —
         the same token paints text and surfaces, so flipping one
         would invert unrelated components. Class-level rules instead.
       - per-component tokens on the component itself (--_bl-* on
         .s-block-link, --_av-* on .s-avatar, --_se-arrow-bc on
         .s-select, --_me-* on .s-menu). These take a raw token and
         are NOT reachable by any .fc- or .bg- utility remap, so a
         component whose colour is only defined this way must be fixed
         by redefining ITS token — that also preserves the geometry the
         token feeds (triangle sides, avatar radius, selected accent).

     Palette (GitHub-dark family):
       base bg        #14181d
       elevated       #1c2128
       elevated-2     #222831 (code, inputs, nested)
       header/footer  #0d1117
       border subtle  #262c33   border component #2d333b
       text primary   #e6edf3   text body #c4cdd6   muted #9198a1
       link/accent    #5fb0e6   hover #9bd4ff
       vote/orange    #d98b3a (accepted check / vote arrows accent)
       success/green  #3fb950
       tag bg/text    #20303d / #8cc6f0
     ============================================================ */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ------------------------------------------------- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* The smaller network sites (every *.stackexchange.com Q&A site
     plus Super User / Server Fault / Ask Ubuntu / MathOverflow /
     Stack Apps) tile a LIGHT "site-background-image.svg" texture
     across the whole <body>. It paints over our dark bg-color and
     washes the entire page near-white — invisible to a bg-COLOR
     audit. Stack Overflow itself ships no body texture, so killing
     it here is safe and fixes every per-site skin at once. */
  html,
  body,
  body.unified-theme {
    background-image: none !important;
  }

  body.unified-theme {
    background-color: #14181d !important;
  }

  /* Stacks paints every custom scrollbar THUMB (code blocks, textareas, the modal
     dialog, the site-switcher pane, every `.overflow-*` utility) from one token,
     `--scrollbar: hsla(0,0%,0%,.2)` — 20% BLACK, which on the darkened surfaces
     is indistinguishable from the track: a wide code block gives no hint that it
     scrolls. The token feeds nothing but `::-webkit-scrollbar-thumb`, so flipping
     it to a translucent light is safe. Declared on `body`, not `:root`. */
  body,
  body.unified-theme {
    --scrollbar: rgba(255, 255, 255, 0.22) !important;
  }

  /* Generic light-surface neutralizers (broad, then re-elevate
     specific surfaces below). These hit the common Stacks bg
     utility classes that paint white/near-white. */
  .bg-white,
  .s-page,
  #content,
  .container,
  #mainbar,
  #mainbar-full,
  .snippet-hidden,
  .ws-nowrap.bg-white {
    background-color: transparent !important;
  }

  /* Stacks ships a full set of HOVER utilities — `h:bg-black-100`,
     `h:fc-black-600`, … — and compiles each one grouped with its static
     sibling as `.bg-black-100, .h\:bg-black-100:hover, … { … !important }`.
     The `:hover` arm therefore lands at TWO simple selectors with `!important`,
     which out-ranks every one-class override in this file: our `.bg-black-*`
     surface remap and our `.fc-black-*` text lift both apply at rest and are
     thrown away the moment the pointer arrives. Nothing in a load-time scan
     can see it, and the elements carrying them live in flyouts (the topbar
     "Products" panel painted a #d6d9dc card under our grey label, ~1.1:1) and
     in the left rail (the "Collectives" / "Stack Internal" section links go to
     var(--black-600) #0c0d0e, pure black on the dark rail).
     Matched as attribute selectors: the class name contains a colon, and
     `[class~="…"]` keeps the same 2-selector weight without escaping. Declared
     HERE, before the component sections, so the specific tag / button /
     block-link hovers further down still win at equal specificity. */
  [class~="h:bg-white"]:hover,
  [class~="h:bg-black-050"]:hover,
  [class~="h:bg-black-075"]:hover,
  [class~="h:bg-black-100"]:hover,
  [class~="h:bg-black-150"]:hover,
  [class~="h:bg-black-200"]:hover,
  [class~="h:bg-black-225"]:hover {
    background-color: #222831 !important;
  }

  [class~="h:bg-purple-100"]:hover,
  [class~="h:bg-purple-200"]:hover {
    background-color: #2b2545 !important;
  }

  [class~="h:fc-black-300"]:hover,
  [class~="h:fc-black-350"]:hover,
  [class~="h:fc-black-400"]:hover,
  [class~="h:fc-black-450"]:hover,
  [class~="h:fc-black-500"]:hover,
  [class~="h:fc-black-600"]:hover,
  [class~="h:fc-dark"]:hover,
  [class~="h:fc-medium"]:hover {
    color: #e6edf3 !important;
  }

  [class~="h:fc-blue-500"]:hover,
  [class~="h:fc-blue-600"]:hover {
    color: #9bd4ff !important;
  }

  /* ---- Headings & text -------------------------------------- */
  /* `h2:not([style*="color"])` spares the network hub's /sites grid: each of
     its 183 tiles is a community's brand colour with a hand-paired ink set
     INLINE on the <h2> (#444 on Stack Overflow's #eaeaea, #1c69a4 on
     Webmasters' #9ce4fe, white on the dark ones). We keep the brand tiles, so
     forcing one light ink over all of them makes every pale tile's name
     invisible — and an `!important` cannot yield to a plain inline value, so
     the arm has to not match. Measured 2026-08-09: /sites is the only page in
     the network with an inline-coloured heading. */
  h1, h2:not([style*="color"]), h3, h4, h5, h6,
  .fs-headline1, .fs-headline2, .fs-title, .fs-subheading,
  .s-prose h1, .s-prose h2, .s-prose h3, .s-prose h4 {
    color: #e6edf3 !important;
  }

  .fc-black-800, .fc-black-900, .fc-black-700,
  .fc-dark, .fc-medium {
    color: #e6edf3 !important;
  }

  .fc-black-600, .fc-black-500,
  .fc-medium,
  .post-signature .user-action-time,
  .mod-message, .subheader h1 {
    color: #c4cdd6 !important;
  }

  /* fc-black-400 (#636b74) and 350/300/200 are SE's muted greys
     — lift to a legible muted grey on dark. These are used for
     timestamps, share/edit links, metadata, nav item text. */
  .fc-black-450, .fc-black-400, .fc-black-350,
  .fc-black-300, .fc-black-250, .fc-black-200,
  .fc-light, .s-description, .fs-caption,
  .relativetime, .relativetime-clean,
  .s-user-card--time, .s-link__muted,
  .js-share-link, .js-suggest-edit-post,
  .s-navigation--item, .disabled-link,
  .v-visible-sr, .post-menu .lsep,
  .s-post-summary--stats-item,
  .s-empty-state, .s-empty-state p,
  .s-empty-state .fs-body2,
  .s-prose .fc-light,
  .revision-comment, span.revision-comment {
    color: #9198a1 !important;
  }

  /* `.s-link__muted` reads `--_li-fc: var(--black-400)`, the SAME token as the
     metadata it sits inside (a question list's `.s-user-card--time` wraps one),
     so it belongs in the group above, not with 500/600 — grouped there it read a
     full step brighter than its own container. Its hover token is `--black-500`;
     the rest colour is `!important`, so the arm is required or the generic
     `a:hover` cannot reach it. */
  .s-link__muted:hover {
    color: #c4cdd6 !important;
  }

  /* `.fc-black` carries NO numeric step: it is pure #000, Stacks' darkest ink,
     and a separate utility from the `.fc-black-NNN` scale above. The network
     home (stackexchange.com) is built on it — the featured-user names, the "Top
     sites" list and the hero's inline links all carry it, so without this ~45
     labels render invisible on the dark cards. Declared AFTER the muted scale
     because Stacks declares it last too: elements carrying both must resolve to
     the prominent ink, not the metadata grey. The two-class
     `.iconLogoNew.fc-black` rule further down still wins for the auth-page
     wordmark. */
  .fc-black {
    color: #e6edf3 !important;
  }

  /* The `.fc-purple-*` scale runs dark like the blue one and is the only other
     chromatic ink SE uses for real labels: `--purple-500` #393fac is 1.9:1 on a
     card (the network home "Featured" chip) and `--purple-400` #555bce paints
     the Collectives/Staging-Ground glyphs at 3.2:1. Steps 100-300 are already
     light enough on dark and are left alone. */
  .fc-purple-400,
  .fc-purple-500,
  .fc-purple-600,
  .fc-purple-700,
  .fc-purple-800,
  .fc-purple-900 {
    color: #a78bfa !important;
  }

  /* The "Skip to main content" link is clipped to 1px until it takes focus,
     then expands to a full-width 1280x44 bar with SE's white background. Our
     text lift paints its label #c4cdd6, so the first Tab press on any network
     page produces a blinding white band with a near-invisible label on it.
     No load-time DOM scan sees it — the element has no size until focused. */
  .s-topbar--skip-link,
  .s-topbar--skip-link:focus,
  a.s-topbar--skip-link:focus {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The BLUE end of the Stacks colour scale is as dark as the black scale and
     was never remapped: `.fc-blue-400` is #1b75d0 (3.4:1 on an elevated card —
     every chat room-card title and its "More info" link reads at that), and
     500 upwards are darker still. The `.fc-*` utilities are `!important` in
     Stacks, so a bare `a { color }` never wins against them — they need their
     own remap, exactly like `.fc-black-*`. Numbers run DARKER on the light
     site, so on dark they run brighter. */
  .fc-blue-400 {
    color: #5fb0e6 !important;
  }

  .fc-blue-500,
  .fc-blue-600,
  .fc-blue-700,
  .fc-blue-800,
  .fc-blue-900 {
    color: #6fb3e8 !important;
  }

  /* The SELECTED horizontal nav pill (.s-navigation--item.is-selected — the
     "Profile"/"Activity" sub-nav on a user page, and similar sort tabs) is
     filled with SE's theme-primary ORANGE (#e7700d) and natively carries
     WHITE text. The broad `.s-navigation--item` muted-grey rule above
     flattened that to grey #9198a1 on orange (~1.9:1, illegible). Restore the
     bright label on the selected pill; the unselected items stay muted. */
  .s-navigation--item.is-selected,
  a.s-navigation--item.is-selected,
  .s-navigation--item.is-selected .s-navigation--item-text {
    color: #ffffff !important;
  }

  /* …but the MUTED variant of the same component never uses the brand orange:
     `.s-navigation.s-navigation__muted` re-points
     `--_na-item-selected-bg: var(--black-150)` (#f1f2f3) with a near-black
     `--_na-item-selected-fc`. That variant is the vertical rail down a user
     profile (Summary / Answers / Questions / Tags / Badges / Reputation / …),
     so the white-label rule above rendered WHITE ON A WHITE PILL and the
     current section was unreadable. The plain `.s-navigation` beside it (the
     "Profile / Activity" pair, same `.is-selected` class) must keep its orange
     pill — so scope by the muted variant's own token, not by the class.
     `--_na-item-selected-bg-hover` is deliberately left alone: Stacks points it
     at `--_na-item-bg` (`none`), i.e. natively the pill drops on hover and the
     white label sits on the page — which stays legible on dark. */
  .s-navigation__muted,
  .s-navigation.s-navigation__muted {
    --_na-item-selected-bg: #2d333b !important;
    --_na-item-selected-fc: #e6edf3 !important;
  }

  /* HOVER on an unselected `.s-navigation--item` (the top-bar "About / Products /
     Stack Internal" links, and the same control on a user page's sub-nav). Stacks
     paints it from `--_na-item-bg-hover: var(--black-150)` — a near-white #e3e6e8
     pill, and the muted-grey label rule above then reads ~1.9:1 on it. The colour
     lives ONLY in the component token, so no `.bg-*` utility remap reaches it, and
     the node is styled only while the pointer is over it, so no load-time scan
     sees it. `:not(.is-selected)` is load-bearing: Stacks re-points
     `--_na-item-bg-hover` at the darker brand orange from the `.is-selected`
     modifier, so an unguarded token override out-!importants that and paints the
     OPEN item's pill dark grey. */
  .s-navigation--item:not(.is-selected) {
    --_na-item-bg-hover: #21262d !important;
    --_na-item-fc-hover: #e6edf3 !important;
  }

  /* Inside the top bar the component token is NOT what paints: a separate rule
     `.s-topbar .s-navigation .s-navigation--item:not(.is-selected):hover` fills
     from `var(--theme-topbar-item-background-hover, var(--black-200))`, and no
     network site defines that theme token — so every one of them falls back to
     the near-white #e3e6e8. Declare the fill directly here; `:not(.is-selected)`
     leaves the open item's brand-orange pill alone. */
  .s-topbar .s-navigation .s-navigation--item:not(.is-selected):hover,
  .s-topbar .s-popover .s-navigation .s-navigation--item:not(.is-selected):hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  .s-navigation--item:not(.is-selected):hover,
  .s-navigation--item:not(.is-selected):hover .s-navigation--item-text {
    color: #e6edf3 !important;
  }

  /* The user-card display NAME (`.s-user-card--link` — the author link under
     every post and in the sidebar asker lists) is a real link SE paints its
     link blue. It was grouped with the timestamps in the muted-grey list
     above, which flattened all 74 of them on a question page to the same grey
     as the metadata around them — the name stopped reading as a link. Restore
     the accent; `.s-user-card--time` beside it stays muted. */
  .s-user-card--link,
  a.s-user-card--link,
  .s-user-card--info .s-user-card--link {
    color: #5fb0e6 !important;
  }

  .s-user-card--link:hover,
  a.s-user-card--link:hover {
    color: #9bd4ff !important;
  }

  /* …but a user with no profile to link to (a deleted account) is a bare
     <span class="s-user-card--link">, which SE leaves at the body ink. The
     classless arm above painted it the accent, so the ONE name on a question
     page that is not clickable read brighter than the 71 that are. Match the
     `.s-user-card--time` it shares its row with. */
  span.s-user-card--link,
  .s-user-card--info span.s-user-card--link {
    color: #9198a1 !important;
  }

  /* `.fs-caption` is a SIZE utility, not a colour: SE puts it on small ACCENT
     text and on small LINKS too. Our blanket muted-grey `.fs-caption` rule
     above swallowed both — the sidebar "Last 1 hr" activity accent
     (`.fc-orange-400`, SE's theme orange) and the login page's "Forgot
     password?" link (`a.s-link.fs-caption`) both rendered as plain grey
     metadata. Re-assert the accent/link colour on those two shapes; the
     specificity (2 classes) beats the size utility. */
  .fc-orange-400,
  .fs-caption.fc-orange-400,
  .fc-orange-400.fs-caption {
    color: #d98b3a !important;
  }

  a.s-link.fs-caption,
  .fs-caption a.s-link {
    color: #5fb0e6 !important;
  }

  /* …and the hover arm those two shapes need. The generic `a:hover` accent is
     unimportant, so the `!important` rest colour above out-ranks it and the
     caption link is the one link on the page with no hover feedback (SE's own
     `.s-link:hover` darkens it). */
  a.s-link.fs-caption:hover,
  .fs-caption a.s-link:hover {
    color: #9bd4ff !important;
  }

  /* …but a `.relativetime` inside an anchor is HALF of that link's label —
     the post signature's "edited <date>" is one <a> to the revision history,
     and the blanket mute above greyed the date while the word "edited" beside
     it stayed the accent, splitting one link into two colours. Inherit so the
     span always matches whatever colour its anchor resolves to. */
  a .relativetime,
  a span.relativetime,
  a .relativetime-clean {
    color: inherit !important;
  }

  /* Site-switcher "Or search from our full list:" hint and other
     plain body-size helper text default to SE's near-black #3b4045
     — lift to a legible muted grey on dark. */
  .ps-relative .fs-body2,
  .site-switcher .fs-body2,
  .modal-content .fs-body2,
  .s-popover .fs-body2,
  .grid--cell > .fs-body2,
  span.flex--item.fs-body2 {
    color: #9198a1 !important;
  }

  /* `.ps-relative` is a layout utility, so the helper-text mute above reaches
     any body-size text inside a positioned box. An explicit dark-ink utility
     marks a heading, not helper text — the "Try Stack Overflow for Agents"
     sidebar widget rendered its title greyer than its own subtitle. */
  .ps-relative .fs-body2.fc-black-700,
  .s-popover .fs-body2.fc-black-700,
  .modal-content .fs-body2.fc-black-700,
  .grid--cell > .fs-body2.fc-black-700 {
    color: #e6edf3 !important;
  }

  /* Same collision on the BLUE end: the mute is 2 classes and the `.fc-blue-*`
     remap is 1, so a body-size element carrying an explicit link-blue utility
     lost it. /collectives renders its explainer card's title this way and it
     came out the same grey as the metadata, beside a `.fc-blue-500` caption in
     the same card that kept the accent. */
  .fs-body2.fc-blue-400,
  .fs-body2.fc-blue-500,
  .fs-body2.fc-blue-600,
  .fs-body2.fc-blue-700 {
    color: #6fb3e8 !important;
  }

  /* Labels, strong metadata, user-card rows: dark #3b4045 by
     default — lift so they read on dark surfaces. */
  .s-label,
  label.s-label,
  .s-user-card--rep,
  .s-user-card--awards,
  .s-prose strong.fc-black-500,
  .post-layout strong,
  .grid--cell strong,
  .fw-bold.fc-black-500 {
    color: #c4cdd6 !important;
  }

  /* ---- Links ------------------------------------------------ */
  a, .s-link,
  .comment-copy a, .s-prose a,
  .s-tag.post-tag a, .post-tag {
    color: #5fb0e6;
  }

  /* question/answer title links default to SE's dark #3b4045 —
     force the accent so sidebar Linked/Related lists read. */
  .question-hyperlink,
  .answer-hyperlink,
  a.question-hyperlink,
  .spacer .question-hyperlink,
  .related a, .linked a {
    color: #6fb3e8 !important;
  }

  a:hover, .s-link:hover, .s-prose a:hover,
  .question-hyperlink:hover, .answer-hyperlink:hover {
    color: #9bd4ff;
  }

  /* `.s-link__inherit` is Stacks' explicit opt-OUT of the link colour
     (`--_li-fc: inherit`): SE uses it where an anchor must read as the plain
     text around it — the question header's "Modified <date>", a Collectives
     card whose whole body is one link, the Hot Network Questions heading. Our
     `.s-link` arm above ties with Stacks' own `.s-link` and wins on order, so
     every one of them rendered accent-blue among plain siblings. Two classes
     beats that arm; no `!important`, so the places we DO paint deliberately
     (`#sidebar a`, `.fc-blue-400`, the HNQ heading) still win. */
  a.s-link__inherit,
  .s-link.s-link__inherit {
    color: inherit;
  }

  /* VISITED links. The generic accent rule above carries no `!important`, so
     SE's `:visited` rules — one pseudo-class more specific — win on every link a
     returning reader has already opened: post bodies and comments drop to
     `--theme-link-color-visited` (#155ca2 on Stack Overflow, 2.6:1 on the page
     base) and every `.s-link` to `--_li-fc-visited` (`--purple-500` #393fac,
     1.9:1). Two arms are needed because a `:visited` override is not reliable:
     some engines refuse to let a later author rule repaint an already-visited
     link, so the FLOOR below (no `:visited`, `!important`) guarantees the
     accent, and the violet arm — Stacks' own default visited hue, lifted to read
     on dark — takes over wherever `:visited` styling does apply and keeps the
     read/unread signal. The `:not()` chain mirrors SE's own exclusions: tags,
     badges and buttons are not link-coloured and must keep their own fill. */
  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn),
  .comment-copy a:not(.badge):not(.s-btn) {
    color: #5fb0e6 !important;
  }

  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):hover,
  .comment-copy a:not(.badge):not(.s-btn):hover {
    color: #9bd4ff !important;
  }

  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited,
  .comment-copy a:not(.badge):not(.s-btn):visited,
  .s-link:not(.s-btn):not(.post-tag):not(.badge-tag):visited {
    color: #b09ae0 !important;
  }

  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited:hover,
  .comment-copy a:not(.badge):not(.s-btn):visited:hover,
  .s-link:not(.s-btn):not(.post-tag):not(.badge-tag):visited:hover {
    color: #d3c4f5 !important;
  }

  /* Same two arms for the Help Center index. Its FAQ lists are
     `.wiki-ph-content`, not `.s-prose`, so the floor above never reached
     them and every link a returning reader has opened drops to SE's
     `a:not([class*="s-"]):visited` colour — #155ca2, 2.6:1 on the page base.
     (Chromium refuses to repaint an already-visited link from an injected
     sheet, so this is only observable in the computed cascade there; the
     floor is what guarantees the accent either way.) */
  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn) {
    color: #5fb0e6 !important;
  }

  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):hover {
    color: #9bd4ff !important;
  }

  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited {
    color: #b09ae0 !important;
  }

  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited:hover {
    color: #d3c4f5 !important;
  }

  /* The user-card and user-list anchors are BARE `<a>` with no class, so the
     unimportant accent above loses to SE's five-`:not()` `:visited` rule and a
     returning reader's already-opened tag / name / timestamp links drop to
     #155ca2, 2.4:1 on the page base — visibly dimmer than the siblings beside
     them. Same two arms as the prose links: an `!important` floor that holds
     wherever the engine refuses to repaint a visited link, plus the violet
     that keeps the read/unread signal where `:visited` styling does apply. */
  .user-tags a,
  .s-user-card--link a,
  .s-user-card--awards a,
  #users-legend a {
    color: #5fb0e6 !important;
  }

  .user-tags a:hover,
  .s-user-card--link a:hover,
  .s-user-card--awards a:hover,
  #users-legend a:hover {
    color: #9bd4ff !important;
  }

  .user-tags a:visited,
  .s-user-card--link a:visited,
  .s-user-card--awards a:visited,
  #users-legend a:visited {
    color: #b09ae0 !important;
  }

  .user-tags a:visited:hover,
  .s-user-card--link a:visited:hover,
  .s-user-card--awards a:visited:hover,
  #users-legend a:visited:hover {
    color: #d3c4f5 !important;
  }

  /* The RSS "… questions feed" link at the foot of every list page. The Q&A
     sites let the accent above reach it, but the network home ships its own
     `#feed-link a { color: #777 }` — 4.7:1 on SE's white page, 4.0:1 once the
     page goes dark, and the only link on stackexchange.com that is not the
     accent. Match the rest of the network. */
  #feed-link a {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Top bar / global navigation
     ============================================================ */
  .s-topbar,
  .top-bar,
  .js-top-bar {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #262c33 !important;
    box-shadow: 0 1px 0 rgba(0, 0, 0, 0.4) !important;
  }

  .s-topbar .s-topbar--item > .s-btn,
  .s-topbar .-link,
  .topbar-links .links-container .topbar-icon,
  .s-topbar a {
    color: #c4cdd6 !important;
  }

  .s-topbar .s-topbar--item > .s-btn:hover,
  .s-topbar .-link:hover {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The search-syntax popover hangs off the top-bar searchbar, so its body links
     ("Search help") are matched by the `.s-topbar a` chrome rule above and lose
     SE's link blue — the only real link in the panel then reads as more hint text.
     Scope the accent to the hint block: a blanket `.s-topbar .s-popover a` would
     also repaint the `.s-block-link` menu rows in the other top-bar popovers. And
     `:not(.s-btn)` spares the filled "Ask a question" CTA sharing this panel's
     footer row — it needs its white-on-blue label, not the link accent. */
  .s-topbar .js-search-hints a:not(.s-btn),
  .s-topbar .js-search-hints a.s-link:not(.s-btn) {
    color: #5fb0e6 !important;
  }

  .s-topbar .js-search-hints a:not(.s-btn):hover {
    color: #9bd4ff !important;
  }

  /* Same trap, the site-switcher pane. Its whole-row `.s-block-link` entries
     are deliberately grey (the row itself is the hover target), but the pane
     also carries INLINE links inside sentences — "help" / "chat" beside the
     current site, "Sign up"/"log in" in "Sign up or log in to customize your
     list.", and the "company blog" in the header. SE paints all of them
     `--blue-500`; `.s-topbar a` above flattens them to the pane's body grey
     and SE draws no underline, so those words carry no affordance at all.
     Scoped to the three inline shapes so the block rows stay grey. */
  .siteSwitcher-dialog a.login-link,
  .siteSwitcher-dialog .related-links a,
  .siteSwitcher-dialog .header a.float-right {
    color: #5fb0e6 !important;
  }

  .siteSwitcher-dialog a.login-link:hover,
  .siteSwitcher-dialog .related-links a:hover,
  .siteSwitcher-dialog .header a.float-right:hover {
    color: #9bd4ff !important;
  }

  /* EVERY topbar dropdown trigger (help "?", inbox, achievements, the network
     site-switcher) gets `.is-selected` while its dialog is open, and SE fills
     the selected item with #e3e6e8 — a white pill in our dark topbar carrying
     a near-invisible grey glyph. Only exists in the OPEN state, so no
     load-time scan sees it. Same treatment as the hamburger below. */
  .s-topbar .s-topbar--item.is-selected,
  a.s-topbar--item.is-selected,
  .s-topbar--item.is-selected {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* …and the same fill lands on plain HOVER, from the same Stacks rule
     (`.s-topbar .s-topbar--item:not(.s-topbar--item__unset):hover` sets
     `--_tb-item-bg: var(--theme-topbar-item-background-hover, var(--black-200))`
     and no network site defines that theme token). Only the OPEN state was
     covered above, so merely passing the pointer over the help "?" / inbox /
     achievements / site-switcher icon painted a #e3e6e8 pill under our
     #c4cdd6 glyph — about 1.2:1, the glyph disappears under the cursor.
     `:not(.s-topbar--item__unset)` is load-bearing and mirrors SE's own
     selector: the "Log in" / "Sign up" buttons carry `.s-topbar--item` too,
     and this rule out-specifies our `.s-btn__filled:hover` accent. */
  .s-topbar .s-topbar--item:not(.s-topbar--item__unset):hover,
  .s-topbar .s-topbar--item:not(.s-topbar--item__unset):hover .svg-icon {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* The site wordmark is a `.s-topbar--logo` link and takes the SAME treatment
     from its own token (`--_tb-logo-bg`), so hovering the logo filled a
     near-white #e3e6e8 pill behind a wordmark that our theme leaves light —
     white-on-#e3e6e8, the logo all but vanishes under the pointer. */
  .s-topbar a.s-topbar--logo:hover,
  .s-topbar a.s-topbar--logo.is-selected,
  .s-topbar .s-topbar--logo:hover {
    --_tb-logo-bg: #21262d !important;
    background-color: #21262d !important;
  }

  /* Mobile hamburger. Once the drawer is open SE marks it `.is-selected`
     and paints it #e3e6e8 — a white tile on our dark topbar with a
     near-invisible light-grey close glyph (~1.2:1). Only visible below the
     `md` breakpoint, so a desktop-only review never sees it. */
  .s-topbar--menu-btn,
  .s-topbar .s-topbar--menu-btn {
    color: #c4cdd6 !important;
  }

  .s-topbar--menu-btn:hover,
  .s-topbar--menu-btn.is-selected,
  .s-topbar .s-topbar--menu-btn.is-selected {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Site-switcher / network dropdown */
  .s-topbar .-logo,
  .s-topbar .-logo .-img {
    filter: none;
  }

  /* The network dropdown draws the "Meta <site>" child row with an
     L-shaped connector built from borders on .L-shaped-icon. SE keeps
     it a light #b9c1c5 that glares as a bright corner line on dark —
     invisible to a bg audit (it's a border). Recolor to a muted grey
     that still reads as a connector but harmonizes with the dark menu. */
  .L-shaped-icon,
  .related-site .L-shaped-icon {
    border-color: #3d444d !important;
  }

  /* The centered Stack Overflow wordmark on the login / auth pages
     is an SVG carrying .fc-black (pure #000) and renders nearly
     invisible black-on-dark. The monochrome "new" logo is fine in
     light — lift it. (Topbar icons already inherit a light color.) */
  svg.iconLogoNew,
  svg.iconLogoNewSm,
  svg.iconGlyphNew,
  .iconLogoNew.fc-black,
  .fc-black.iconLogoNew {
    color: #e6edf3 !important;
    fill: #e6edf3 !important;
  }

  /* Per-site header logos on the non-SO network sites (Super User,
     Server Fault, Ask Ubuntu, MathOverflow, *.stackexchange.com,
     Stack Apps) are <img src="…/logo.svg"> dark wordmarks baked for
     the white site — invisible black-on-dark. They're images we
     can't recolor internally, so apply the standard dark-mode
     luminance invert (hue-rotate keeps brand hues like SU's blue
     bracket). SO uses an inline SVG (handled above), not this img.
     Sites whose header band is a BRAND colour reset this at the end
     of the file — there the wordmark is baked for the band. */
  .site-header--link img,
  a.site-header--link img,
  #hlogo img,
  .-logo img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* The network-site login/auth page centers a per-site wordmark next to the
     Stack Overflow glyph (LogoEmail.png — the dark wordmark baked for the white
     site) as <img class="va-middle"> inside the logo link. It is neither an
     .-logo/#hlogo/.site-header--link img (the rule above misses it) nor the
     inline SVG that SO's own auth page uses, so it renders black-on-dark and
     the site name all but vanishes. Same luminance invert; scoped to the auth
     body so no other image is touched (OAuth icons are inline SVGs, not imgs). */
  body.universal-auth-page a.s-link img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Stack Apps' question summaries carry a 144x119 thumbnail; every post without
     its own screenshot falls back to one of the site's default plates —
     `library-thumb.png` for apps, `script-thumb.png` for scripts — both solid
     white with pale gear line-art (mean luminance 242). A tagged list is a
     column of ~10 of them. Two constraints pin the selector shape: the same
     slot holds user-uploaded screenshots, which must stay untouched (they are
     served from i.sstatic.net and third-party CDNs, never from the site's own
     `/Content/Sites/<site>/Img/`), and that asset directory ALSO holds the
     brand rasters — `icon-48.png`, `apple-touch-icon.png`, `logo.svg` — which
     must not invert. So match the directory AND the `-thumb.png` suffix; any
     further default plate the site adds to the family is covered. */
  img[src*="/Content/Sites/"][src*="-thumb.png"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Global search box in the top bar. Below the `md` breakpoint the searchbar
     is a full-width overlay row (`.s-topbar--searchbar__open`) that Stacks
     fills from `var(--theme-topbar-item-background-hover, var(--black-200))` —
     the same undefined theme token as the topbar items, so it falls back to
     #e3e6e8: tapping the mobile search icon dropped a near-white 390x49 band
     across the top of every page. The legacy `.searchbar` class below matches
     nothing on the current frontend (the live class is the BEM
     `.s-topbar--searchbar`), and the rule only fires inside a media query, so
     a desktop-only review never renders it. */
  .s-topbar .searchbar,
  .top-bar .searchbar,
  .s-topbar .s-topbar--searchbar,
  .s-topbar .s-topbar--searchbar.s-topbar--searchbar__open {
    background-color: #0d1117 !important;
  }

  /* ============================================================
     Search inputs / all text inputs
     ============================================================ */
  .s-input,
  .s-textarea,
  input.s-input,
  textarea.s-textarea,
  input[type="text"],
  input[type="search"],
  input[type="email"],
  input[type="password"],
  input[type="url"],
  input[type="number"],
  textarea,
  select,
  select.s-select,
  .s-select select,
  .s-input__search {
    background-color: #222831 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* The "Sorted by" answer-sort control (and any other native
     <select>) is a bare, unclassed <select> nested inside a
     .s-select div wrapper — SE styles the wrapper and leaves the
     real control its default white #fff with black text. It's short
     (~32px) so it slips the audit height filter, but renders as a
     glaring white pill on dark. Darken its option list too. */
  select option {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The wrapper's up/down caret is a pair of CSS triangles drawn by
     `.s-select:before/:after` from `--_se-arrow-bc: var(--bc-dark) transparent`
     — a two-value border-color shorthand (opaque top/bottom, transparent
     sides) that resolves to #0c0d0e, 1.3:1 on the darkened control, so the
     control looks like it has no caret at all. Redefine the token keeping the
     two-value form: a flat colour would fill the transparent sides and turn
     each triangle into a solid rectangle. */
  .s-select {
    --_se-arrow-bc: #9198a1 transparent !important;
  }

  .s-input:focus,
  .s-textarea:focus,
  input:focus,
  textarea:focus {
    border-color: #5fb0e6 !important;
    box-shadow: 0 0 0 2px rgba(95, 176, 230, 0.25) !important;
  }

  /* Placeholders: legible muted grey, never the input bg */
  .s-input::placeholder,
  .s-textarea::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* The top-bar search icon */
  .s-input__icon, .svg-icon.iconSearch {
    color: #8b949e !important;
  }

  /* Checkboxes & radios (filter panels, ask-flow, notification prefs).
     Stacks renders .s-checkbox / .s-radio-button as appearance:none
     custom controls painted a solid WHITE box/disc — invisible to a
     bg-COLOR audit on the page base but glaring light squares/circles
     on dark (the Questions "Filter" panel and every settings form).
     Darken the unchecked control to an elevated surface; keep the
     accent-blue fill + white glyph for the checked state. */
  input[type="checkbox"],
  input[type="radio"],
  .s-checkbox,
  .s-radio-button {
    background-color: #222831 !important;
    border-color: #2d333b !important;
  }

  input[type="checkbox"]:checked,
  input[type="radio"]:checked,
  .s-checkbox:checked,
  .s-radio-button:checked {
    background-color: #2f6f9f !important;
    border-color: #3b82b8 !important;
  }

  /* ============================================================
     Left navigation sidebar
     ============================================================ */
  #left-sidebar,
  .left-sidebar,
  .left-sidebar--sticky-container,
  .ps-relative.h100.js-pinned-left-sidebar {
    background-color: transparent !important;
  }

  #left-sidebar .pl16,
  .nav-links .nav-links--link,
  .left-sidebar .nav-links--link {
    color: #c4cdd6 !important;
  }

  /* Nav links sit flush on the sidebar at rest: the link AND its
     inner label span (.-link--channel-name) must be transparent —
     the .-link--channel-name elevated-chip rule further down was
     painting a grey box behind every label. Only HOVER and the
     SELECTED item get an elevated background. */
  .nav-links .nav-links--link,
  .left-sidebar .nav-links--link,
  #left-sidebar .nav-links--link,
  .nav-links--link .-link--channel-name,
  .left-sidebar .nav-links--link .-link--channel-name {
    background-color: transparent !important;
  }

  /* Hover surface. The at-rest reset above carries an ID
     (`#left-sidebar .nav-links--link`, 1-0-1-0), so every state rule below it
     must ALSO carry that ID or the reset out-ranks it and the state never
     paints — the sibling `.s-block-link` nav rows (Home, AI Assist, Chat) do
     highlight on hover via their `--_bl-bg` token, so the `.nav-links--link`
     rows (Questions, Tags, Users, Companies) were the only ones in the rail
     with no hover feedback at all. */
  .nav-links--link:hover,
  .left-sidebar .nav-links--link:hover,
  #left-sidebar .nav-links--link:hover,
  #left-sidebar .nav-links .nav-links--link:hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Selected nav item: SE marks it with aria-current="page" (the
     legacy .youarehere class is gone), and paints a full white
     pill (#f1f2f3). Recolor to a dark elevated surface with light
     text + a tasteful SO-orange left accent. Must out-rank BOTH the
     ID-carrying at-rest reset and the hover rule above, so it repeats the
     `#left-sidebar` prefix and sits after them. */
  .left-sidebar .nav-links--link.youarehere,
  .left-sidebar .nav-links--link.youarehere .-link,
  .nav-links--link[aria-current="page"],
  .nav-links--link[aria-current="true"],
  .left-sidebar .nav-links--link[aria-current="page"],
  #left-sidebar .nav-links--link[aria-current="page"],
  #left-sidebar .nav-links--link[aria-current="true"],
  #left-sidebar .nav-links .nav-links--link[aria-current="page"] {
    background-color: #1c2128 !important;
    border-left: 3px solid #d98b3a !important;
    color: #e6edf3 !important;
  }

  #left-sidebar .nav-links .nav-links--link[aria-current="page"]:hover,
  #left-sidebar .nav-links--link[aria-current="page"]:hover {
    background-color: #21262d !important;
  }

  /* keep the selected item's label text bright (overrides the
     generic muted nav-link color) */
  .nav-links--link[aria-current="page"],
  .nav-links--link[aria-current="page"] .-link--channel-name,
  .nav-links--link:hover .-link--channel-name {
    color: #e6edf3 !important;
  }

  /* Purple brand-icon discs (AI Assist, Stack Overflow for Agents,
     Chat). Each glyph (.fc-white) sits on a purple disc
     (.bg-purple-400 = #555bce) ringed by a 4px near-white border
     (.bc-purple-200 = #dfe1fb). That pale ring is invisible on SE's
     white page but reads as a glaring WHITE HALO on dark. Keep the
     purple disc + white glyph (the brand identity) and only retone
     the ring to a dark, harmonized purple so the halo disappears.
     The disc FILL is pinned to the same #555bce it already computes to on the
     light site: a no-op there, and it keeps the white glyph legible for a
     reader who also has SE's own account-level dark mode on, where
     var(--purple-400) flips to a pale lavender #bdc1fe. */
  .nav-links--link .bg-purple-400.bar-circle,
  .nav-links--link div.bg-purple-400,
  .left-sidebar .nav-links--link .bg-purple-400 {
    background-color: #555bce !important;
    border-color: #3b3f73 !important;
  }

  /* Nav item GLYPHS (Home / Questions / Unanswered / Tags / Users /
     Companies, desktop rail and mobile drawer alike). SE paints them via
     `.nav-links--link.-link__with-icon .svg-icon { color: var(--black-500) }`
     — a raw token, not an `.fc-black-*` utility, so the utility remap above
     never reaches them: they render #3b4045 at 1.7:1, and the SELECTED item
     takes var(--black-600) #0c0d0e at 1.1:1 (invisible). The glyph is an
     inheriting `fill:currentColor` path, so setting `color` is enough.
     `:not(.fc-white)` spares the white glyphs on the purple brand discs. */
  .nav-links--link .svg-icon:not(.fc-white),
  .nav-links--link.-link__with-icon .svg-icon:not(.fc-white),
  .left-sidebar .nav-links--link .svg-icon:not(.fc-white) {
    color: #9198a1 !important;
  }

  .nav-links--link:hover .svg-icon:not(.fc-white),
  .nav-links--link[aria-current="page"] .svg-icon:not(.fc-white),
  .left-sidebar .nav-links--link[aria-current="page"] .svg-icon:not(.fc-white) {
    color: #e6edf3 !important;
  }

  /* SE plates the glyph itself on hover/focus/active
     (`.nav-links .nav-links--link.-link__with-icon:hover .svg-icon
     { background: var(--black-100) }`, a raw token) — a near-white 18px
     square behind the lifted glyph. The plate stays one step above the
     row's own hover surface; the purple brand discs carry `.bg-transparent`
     and are spared by `:not(.fc-white)`. */
  .nav-links .nav-links--link.-link__with-icon:hover .svg-icon:not(.fc-white),
  .nav-links .nav-links--link.-link__with-icon:focus .svg-icon:not(.fc-white),
  .nav-links .nav-links--link.-link__with-icon:active .svg-icon:not(.fc-white) {
    background-color: #2d333b !important;
  }

  /* ============================================================
     Main content: question / answers / cards
     ============================================================ */
  #content,
  #question-header,
  .question-page #mainbar,
  .inner-content {
    background-color: transparent !important;
  }

  /* The smaller network sites box #content in a light 1px border
     (#e3e6e8) — a thin light frame around the whole content area.
     SO has no such border; recolor to a subtle dark frame. */
  #content {
    border-color: #262c33 !important;
  }

  /* Cards & elevated panels */
  .s-card,
  .js-post-summary,
  .question-summary,
  .spacer .grid--cell,
  .s-modal--dialog,
  .popup,
  .s-popover,
  .module.community-bulletin,
  .s-notice {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* The question + each answer cell */
  #question,
  .question,
  .answer,
  .post-layout,
  .js-zone-container,
  #answers,
  .answercell,
  .postcell,
  .post-layout--right,
  .post-layout--left {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* dividers between posts */
  .question, .answer,
  .pb8.mb16.bb.bc-black-075,
  .bb.bc-black-075, .bb.bc-black-100,
  .bt.bc-black-075, .bt.bc-black-100,
  #answers-header {
    border-color: #262c33 !important;
  }

  /* Prose body text */
  .s-prose,
  .post-text,
  .js-post-body,
  .comment-copy,
  .wmx100 {
    color: #c4cdd6 !important;
  }

  .s-prose strong, .s-prose b { color: #e6edf3 !important; }

  /* …but not when the bold text IS the link (`<a><strong>title</strong></a>`,
     the usual shape for a cited paper or a linked heading in an answer). The
     bright-prose rules are !important and land on the inner element, so the
     anchor's accent never reaches the rendered text and a bold link becomes
     bold body copy. Same trap for the metadata `strong` rules further down,
     hence the .post-layout / .grid--cell arms. */
  .s-prose a strong, .s-prose a b,
  .comment-copy a strong, .comment-copy a b,
  .post-layout a strong, .grid--cell a strong {
    color: inherit !important;
  }

  /* Stacks draws a quote's left rule as a 4px `::before` filled with
     `--black-300` (#c8ccd0), NOT as a border — `border-left-width` is 0, so a
     border-colour override is a no-op and every quoted passage in every
     answer keeps a bright bar down its left edge. */
  .s-prose blockquote {
    border-left-color: #2d333b !important;
    color: #9198a1 !important;
  }

  .s-prose blockquote::before,
  blockquote::before {
    background-color: #3d444d !important;
  }

  /* SE draws every <hr> as a 1px block with `background-color: #d6d9dc`
     and `border-width: 0` — so a `border-color` override never paints and
     the rules render as bright white lines through answers and the login
     card. Recolor the BACKGROUND (keep the border-color for old markup). */
  hr,
  .s-prose hr,
  .s-card hr {
    background-color: #262c33 !important;
    border-color: #262c33 !important;
  }

  /* Section rules drawn as a BORDER instead of an <hr>: `.s-page-title`
     underlines its heading with #d6d9dc and each help-center category <h3>
     with #e3e6e8. Both are light-theme greys SE never re-tones, so the Help
     Center ships a bright rule under "Help center" and under every category
     ("Asking", "Our model", "Reputation & Moderation", …). */
  .s-page-title,
  div.s-page-title,
  .help-category-box h3,
  .help-center-index h3,
  .help-category-box > h3 {
    border-color: #2d333b !important;
  }

  /* The `.s-page-title` header block's own two text parts. Both take raw tokens
     the `.fc-black-*` utility remap never reaches: the breadcrumb trail
     ("Stack Overflow > Help center") and the standfirst under the H1 sit on
     var(--black-400) #636b74 = 3.0:1, and a breadcrumb link flips to
     `--_br-link-fc: var(--fc-medium)` #3b4045 = 1.5:1 ON HOVER — it all but
     disappears under the pointer, which no load-time scan can see. */
  .s-breadcrumbs--link,
  .s-breadcrumbs .s-breadcrumbs--link,
  .s-page-title--description,
  .s-page-title .s-page-title--description {
    color: #9198a1 !important;
  }

  .s-breadcrumbs--link:hover,
  .s-breadcrumbs .s-breadcrumbs--link:hover {
    color: #c4cdd6 !important;
  }

  /* Accepted answer highlight */
  .answer.accepted-answer,
  .accepted-answer {
    background-color: #16221a !important;
  }

  .accepted-answer .js-vote-count,
  .accepted-answer .vote-count-post {
    color: #e6edf3 !important;
  }

  /* Stacks semantic TEXT tones. `--fc-success` #18864b, `--fc-error` /
     `--fc-danger` #c83232 and `--fc-warning` #9c730d were picked for the
     white site and land 4.0:1 / 3.1:1 / 4.0:1 on the page base — all under
     AA for the 12-13px labels they mark (the editor draft status, form
     validation). Lift each to the palette sibling of the same hue; the
     matching `.bg-*` / `.bc-*` utilities are solid fills that already read
     on dark and must keep the site value. */
  .fc-success {
    color: #3fb950 !important;
  }

  .fc-error,
  .fc-danger {
    color: #f85149 !important;
  }

  .fc-warning {
    color: #d98b3a !important;
  }

  /* The accepted (green check) glyph */
  .accepted-answer-indicator,
  .js-accepted-answer-indicator,
  .iconCheckmarkLg.fc-green-400,
  svg.fc-green-500 {
    color: #3fb950 !important;
  }

  /* ============================================================
     Vote controls
     ============================================================ */
  .js-vote-count,
  .vote-count-post,
  .js-voting-container .fc-black-500 {
    color: #e6edf3 !important;
  }

  .js-vote-up-btn, .js-vote-down-btn,
  .vote-up-off, .vote-down-off,
  .s-btn.s-btn__unset.c-pointer {
    color: #9198a1 !important;
  }

  /* The vote arrows are the only control on a post that signals what a click
     will DO, and SE signals it with the theme orange (`h:bg-theme-primary-200`
     on the button itself). The buttons are also `.s-btn.s-btn__muted`, so the
     generic `.s-btn:hover` grey further down this file — same specificity,
     declared later — was winning and the hovered arrow came up the same
     neutral grey as its idle sibling. Restate at 2 classes + the element so
     both the generic mute and the outlined-button rules lose. */
  .js-vote-up-btn:hover, .js-vote-down-btn:hover,
  .s-btn.js-vote-up-btn:hover, .s-btn.js-vote-down-btn:hover,
  button.s-btn.js-vote-up-btn:hover, button.s-btn.js-vote-down-btn:hover {
    background-color: rgba(217, 139, 58, 0.18) !important;
    color: #d98b3a !important;
  }

  /* The arrow glyph itself: the button is `.s-btn__outlined.s-btn__muted`, and
     that 3-class rule sits LATER in this file than the hover rule above, so it
     out-ranked the accent and the arrow stayed grey inside its orange tint.
     The element qualifier lifts these past it; `.svg-icon` inherits
     currentColor, so colouring the button is enough. */
  button.s-btn.js-vote-up-btn:hover,
  button.s-btn.js-vote-down-btn:hover,
  button.s-btn.js-vote-up-btn:hover .svg-icon,
  button.s-btn.js-vote-down-btn:hover .svg-icon {
    color: #d98b3a !important;
  }

  .js-vote-up-btn.fc-theme-primary,
  .vote-up-on,
  .js-voting-container .fc-orange-400 {
    color: #d98b3a !important;
  }

  /* Bookmark / star */
  .js-bookmark-btn.s-btn__filled,
  .js-saves-btn {
    color: #d98b3a !important;
  }

  /* ============================================================
     Comments
     ============================================================ */
  .comments,
  .comment,
  .comment-text,
  .comments-list,
  .js-comments-container {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .comment {
    border-bottom: 1px solid #20262d !important;
  }

  /* comment action rows carry a light #c4cdd6 border-bottom */
  .comment-actions,
  .js-comment-actions {
    border-color: #20262d !important;
  }

  .comment-copy { color: #b3bcc6 !important; }

  .comment .comment-user,
  .comment a.comment-user {
    color: #6f9ab0 !important;
  }

  /* The POST OWNER's name in comments carries `.owner`, which SE highlights
     with a light-blue #ebf6fa pill background to mark the author — a glaring
     light pill on dark (short at 83x20, so it slips the audit height filter).
     Retone to a subtle dark-blue tint; the #6f9ab0 name still reads on it.
     The bare arms carry it to the post timeline, which repeats the pill
     outside any `.comment` container. */
  .comment .comment-user.owner,
  .comment a.comment-user.owner,
  .comment-user.owner,
  a.comment-user.owner {
    background-color: #16202c !important;
  }

  /* The comment timestamp. SE pins `.comment-date` and its anchor to
     `var(--black-400)` #636b74 with its OWN `!important` at 2-class
     specificity, and the `a .relativetime-clean { color: inherit }` rule
     above hands that value straight to the date span — 3.3:1 on the post
     surface. Mirror SE's specificity so the mute lands on the anchor too. */
  .comment-date,
  .comment-date > a,
  .comment-date a.comment-link {
    color: #9198a1 !important;
  }

  .comment-score, .comment-score b {
    color: #9198a1 !important;
  }

  /* High-value comment scores get warmth tiers on the score number:
     `.hot` (#e0913f, already lifted by the .hot rule) is fine, but SE's
     `.warm` is a dark brown #813f09 (~2:1 dark-on-dark) and `.cool` its
     muted #636b74 (~3:1). Lift both to legible tones — warm to a readable
     amber (distinct from hot), cool to the standard muted grey. */
  .comment-score .warm, .comment-score.warm,
  .comment-actions .warm {
    color: #d98b3a !important;
  }

  .comment-score .cool, .comment-score.cool,
  .comment-actions .cool {
    color: #9198a1 !important;
  }

  .comment-actions .comment-up-on,
  .comment-up:hover {
    color: #d98b3a !important;
  }

  /* "Add a comment" / show more comments link */
  .js-add-link, .js-show-link, .js-link-separator {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Tags
     ============================================================ */
  .post-tag,
  .s-tag,
  a.post-tag,
  a.s-tag,
  .badge-tag,
  a.badge-tag {
    background-color: #20303d !important;
    color: #8cc6f0 !important;
    border-color: #2b4253 !important;
  }

  .post-tag:hover,
  .s-tag:hover,
  a.post-tag:hover,
  a.badge-tag:hover {
    background-color: #2b4253 !important;
    color: #bfe0f7 !important;
  }

  .s-tag.s-tag__moderator { background-color: #3a2b20 !important; color: #e0a878 !important; }

  /* tag count / multiplier badges. The sidebar "Recent tags" widget on the
     network Q&A sites (MathOverflow et al.) keeps SE's #636b74 for the
     count next to each tag — 3.1:1 dark-on-dark. The `×` glyph is a
     SEPARATE element (`.item-multiplier-x`) from the number beside it, so
     lifting only the count leaves the two halves of one label at different
     brightnesses. */
  .s-tag--count, .post-tag-count,
  .item-multiplier,
  .item-multiplier-x,
  .item-multiplier-count,
  .item-multiplier .item-multiplier-count { color: #9198a1 !important; }

  /* ============================================================
     Code blocks + inline code + syntax highlighting
     ============================================================ */
  pre,
  pre.s-code-block,
  .s-code-block,
  .s-prose pre,
  .wmd-preview pre {
    background-color: #222831 !important;
    color: #d9e0e7 !important;
    border: 1px solid #2d333b !important;
  }

  pre code, .s-code-block code {
    background-color: transparent !important;
    color: #d9e0e7 !important;
  }

  /* inline code */
  code,
  .s-prose code,
  kbd {
    background-color: #232a33 !important;
    color: #e3b7a0 !important;
  }

  kbd {
    border-color: #2d333b !important;
    color: #d9e0e7 !important;
    box-shadow: none !important;
  }

  /* highlight.js dark syntax palette */
  .hljs { background: transparent !important; color: #d9e0e7 !important; }
  .hljs-comment, .hljs-quote { color: #8b949e !important; }
  .hljs-keyword, .hljs-selector-tag, .hljs-built_in,
  .hljs-name, .hljs-tag { color: #ff7b72 !important; }
  .hljs-string, .hljs-attr, .hljs-template-tag,
  .hljs-addition, .hljs-regexp { color: #a5d6ff !important; }
  .hljs-number, .hljs-literal, .hljs-type,
  .hljs-variable, .hljs-template-variable,
  .hljs-class .hljs-title, .hljs-selector-attr,
  .hljs-selector-pseudo { color: #79c0ff !important; }
  .hljs-title, .hljs-function .hljs-title, .hljs-section { color: #d2a8ff !important; }
  .hljs-attribute, .hljs-symbol, .hljs-bullet,
  .hljs-meta { color: #ffa657 !important; }
  .hljs-deletion { color: #ff7b72 !important; }
  .hljs-emphasis { font-style: italic; }
  .hljs-strong { font-weight: bold; color: #e6edf3 !important; }
  .hljs-doctag, .hljs-params { color: #c4cdd6 !important; }
  /* Tokens the palette above did not name. SE's own rules for these are more
     specific than `.hljs` (`pre.s-code-block>code .hljs-subst`, 0,2,2), so an
     unlisted token silently keeps its LIGHT-theme colour: `--highlight-color`
     #0c0d0e (1.3:1 — a Python f-string's `{n}` vanishes), `--highlight-*`
     punctuation #3b4045, keyword #01508f, variable #5a7a0d, namespace #b84b01.
     Grouped with the palette entry each one shares its meaning with. */
  .hljs-subst { color: #d9e0e7 !important; }
  .hljs-code { color: #c4cdd6 !important; }
  .hljs-link, .hljs-meta-string { color: #a5d6ff !important; }
  .hljs-meta-keyword, .hljs-selector-class { color: #ff7b72 !important; }
  .hljs-selector-id { color: #79c0ff !important; }

  /* Stacks prettify-style spans (older code) */
  .prettyprint .pln { color: #d9e0e7 !important; }
  .prettyprint .str, .prettyprint .atv { color: #a5d6ff !important; }
  .prettyprint .kwd { color: #ff7b72 !important; }
  .prettyprint .com { color: #8b949e !important; }
  .prettyprint .typ, .prettyprint .atn { color: #79c0ff !important; }
  .prettyprint .lit { color: #79c0ff !important; }
  .prettyprint .pun, .prettyprint .opn, .prettyprint .clo { color: #c4cdd6 !important; }
  .prettyprint .tag { color: #ff7b72 !important; }

  /* ============================================================
     Right sidebar modules (Linked / Related / Hot / Featured)
     ============================================================ */
  #sidebar,
  .sidebar,
  #sidebar .module,
  .module.sidebar-linked,
  .module.sidebar-related,
  .module.sidebar-featured,
  .module.community-bulletin,
  .module.newsletter-ad,
  .s-sidebarwidget,
  .s-sidebarwidget--content {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .s-sidebarwidget {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .s-sidebarwidget--header,
  .s-sidebarwidget .s-sidebarwidget--header {
    background-color: #20262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Hot Network Questions (yellow widget) -> warm-tinted dark */
  .s-sidebarwidget__yellow,
  .s-sidebarwidget.s-sidebarwidget__yellow {
    background-color: #211d14 !important;
    border-color: #3a3320 !important;
  }

  /* Widget headers: ONE consistent treatment across all page types.
     SE renders the "Overflow Blog"/"Featured on Meta" yellow widget
     header gold but the "Collectives"/"Community activity" regular
     headers near-black (#3b4045 -> white) — visually inconsistent on
     dark. Unify to the same warm gold-amber so every widget header
     reads the same, regardless of page (list/question/code/tags). */
  .s-sidebarwidget__yellow .s-sidebarwidget--header,
  .s-sidebarwidget .s-sidebarwidget--header {
    background-color: #20262d !important;
    color: #e8c98a !important;
  }

  /* "Hot Network Questions" is a legacy `.module` widget like Linked/Related,
     NOT an `.s-sidebarwidget`, so its plain <h4> belongs with those two, not
     with the filled gold band above. Two things broke it: SE ships the widget
     as `<div id="hot-network-questions" class="module tex2jax_ignore">` — the
     hook is an ID now, so a `.module.hot-network-questions` selector matches
     nothing network-wide — and the heading TEXT is an <a> that SE explicitly
     opts out of the link colour with `.s-link__inherit`, which our blanket
     `#sidebar a` accent overrode. The heading therefore rendered link-blue
     right under a white "Related" heading of the same kind. */
  #hot-network-questions h4,
  #hot-network-questions h4 a,
  #hot-network-questions h4 a.s-link__inherit {
    color: #e6edf3 !important;
  }

  /* The header band inside the yellow widget takes its border from the generic
     `.s-sidebarwidget--header` rule above, so the widget frame is warm #3a3320
     while the rule under "The Overflow Blog" / "Featured on Meta" stays the
     cold neutral — a grey line across a brown card. SE keeps both on the same
     gold; keep both on the same warm dark. */
  .s-sidebarwidget__yellow .s-sidebarwidget--header,
  .s-sidebarwidget.s-sidebarwidget__yellow .s-sidebarwidget--header {
    background-color: #2a2417 !important;
    border-color: #3a3320 !important;
  }

  /* The header-band fill above assumes the header is the widget's full-width
     `li` (Overflow Blog / Featured on Meta). The "Community activity" widget
     instead puts `.s-sidebarwidget--header` on an INLINE div inside a flex row
     next to the "Last 1 hr" caption — so the fill painted a grey rectangle
     that stopped dead mid-row. Keep the band on the li; the inline div header
     keeps only the header TEXT colour, on the widget's own surface. */
  .s-sidebarwidget div.s-sidebarwidget--header,
  .s-sidebarwidget div.s-sidebarwidget--header.s-sidebarwidget--header {
    background-color: transparent !important;
  }

  /* Overflow Blog / Featured-on-Meta links: SE wraps these widgets
     in .s-anchors__grayscale, which forces the links to a near-black
     GRAYSCALE tone via -webkit-text-fill-color (NOT plain color) — so
     a `color:` override alone leaves the rendered pixels dim grey on
     dark (the list-page "dim links" bug; the question page looked OK
     only because its prominent widgets use .question-hyperlink which
     we already theme). Override BOTH color and -webkit-text-fill-color
     so the links render the readable blue accent on EVERY page type. */
  #sidebar .s-anchors__grayscale a,
  #sidebar .s-sidebarwidget__yellow a,
  #sidebar .s-sidebarwidget a.js-gps-track,
  .s-sidebarwidget.s-anchors__grayscale a {
    color: #5fb0e6 !important;
    -webkit-text-fill-color: #5fb0e6 !important;
  }

  #sidebar .s-anchors__grayscale a:hover,
  #sidebar .s-sidebarwidget__yellow a:hover,
  #sidebar .s-sidebarwidget a.js-gps-track:hover {
    color: #9bd4ff !important;
    -webkit-text-fill-color: #9bd4ff !important;
  }

  .module.sidebar-linked .spacer .answered,
  .module.sidebar-related .spacer .answered-accepted,
  #sidebar .answered,
  #sidebar .unanswered {
    color: #c4cdd6 !important;
  }

  #sidebar .question-hyperlink,
  #sidebar a {
    color: #5fb0e6 !important;
  }

  /* Accepted-answer vote pill. SE fills it a solid green (#18864b) with white
     text everywhere it appears; the list page's `.status.answered-accepted`
     already keeps that solid treatment, so the sidebar's Linked/Related pills
     must not render the same state as a faint tint — one semantic, one look. */
  #sidebar .answered-accepted, #sidebar .accepted {
    background-color: #1f7a45 !important;
    color: #ffffff !important;
  }

  #sidebar .answered {
    background-color: #20303d !important;
    color: #8cc6f0 !important;
  }

  /* Linked/Related sidebar vote-count pills. `default`/`large`/`extra-large`
     are SIZE classes, NOT states: match on the STATE only, never the size, or
     the same white pill comes back one size up (a `.large` "236" shipped
     glaring white while the `.default` siblings beside it were correct). The
     plain no-accept pill keeps SE's white #f1f2f3 fill with near-black
     #3b4045 text, and it is short (38x21) so it slips the audit height
     filter — darken it. An ACCEPTED (green) or ANSWERED (blue) pill must keep
     its fill, and these selectors would out-specify the state rules below, so
     exclude the two state classes explicitly. */
  .answer-votes:not(.answered):not(.answered-accepted),
  #sidebar .answer-votes:not(.answered):not(.answered-accepted),
  .module .answer-votes:not(.answered):not(.answered-accepted) {
    background-color: #20262d !important;
    color: #9198a1 !important;
  }

  #sidebar .status.unanswered, #sidebar .iconClock {
    color: #9198a1 !important;
  }

  /* "Featured on Meta" / list rows */
  .s-sidebarwidget--item,
  .s-sidebarwidget .s-sidebarwidget--item {
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Stacks separates two stacked `--content` blocks with a `--black-150`
     #e3e6e8 top rule on the second one (`+` sibling), a path the `--item`
     arm above never reaches. The widget's own surface/ink rules carry no
     border-colour, so an accordion sidebar draws bright hairlines. */
  .s-sidebarwidget--content,
  .s-sidebarwidget .s-sidebarwidget--content {
    border-color: #2d333b !important;
  }

  /* Stacks deliberately de-links plain anchors inside a sidebar widget
     (`.s-sidebarwidget:not(.s-anchors) a:not(…)` → `--black-600`), i.e. they
     are the widget's PROMINENT ink, not the accent. That reads 1.2:1 once the
     widget is dark, and the rule's five-way `:not()` chain out-ranks the page
     accent everywhere the `#sidebar` id is absent — the /legal pages, whose
     whole navigation is such a widget. Map the ink, not the link colour. */
  .s-sidebarwidget--item a,
  .s-sidebarwidget--content a {
    color: #e6edf3 !important;
  }

  .s-sidebarwidget--item a:hover,
  .s-sidebarwidget--content a:hover {
    color: #9bd4ff !important;
  }

  /* ============================================================
     Questions list / home
     ============================================================ */
  .s-post-summary,
  .js-post-summary,
  .question-summary,
  .s-post-summary--content {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .s-post-summary {
    border-bottom: 1px solid #20262d !important;
  }

  .s-post-summary--content-title a,
  .s-post-summary .question-hyperlink {
    color: #c8d6f0 !important;
  }

  .s-post-summary--content-title a:hover { color: #9bd4ff !important; }

  .s-post-summary--content-excerpt { color: #9198a1 !important; }

  /* vote / answer / view stat pills */
  .s-post-summary--stats-item,
  .s-post-summary--stats-item-number,
  .stats .vote-count-post,
  .stats .views {
    color: #9198a1 !important;
  }

  /* View-count HEAT tiers. Stacks marks a busy question's stats item
     `.is-warm` (yellow-500), `.is-hot` (orange-500) or `.is-supernova`
     (red-500) — the only signal on a list row that a question is trending.
     Our blanket `.s-post-summary--stats-item` muted-grey rule (and its
     -number/-unit children rule) flattened all three, so a 18k-view hot
     question rendered the exact same grey as a 5-view one. Restore the three
     tiers, retoned for dark. */
  .s-post-summary--stats-item.is-warm,
  .s-post-summary--stats-item.is-warm .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.is-warm .s-post-summary--stats-item-unit {
    color: #d3a84a !important;
  }

  .s-post-summary--stats-item.is-hot,
  .s-post-summary--stats-item.is-hot .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.is-hot .s-post-summary--stats-item-unit {
    color: #e0913f !important;
  }

  .s-post-summary--stats-item.is-supernova,
  .s-post-summary--stats-item.is-supernova .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.is-supernova .s-post-summary--stats-item-unit {
    color: #f0776b !important;
  }

  /* "answered & accepted" pill: filled green with white text
     (matches SE), readable contrast. */
  .s-post-summary--stats-item.has-answers.has-accepted-answer,
  .s-post-summary--stats-item.has-accepted-answer,
  .status.answered-accepted {
    background-color: #1f7a45 !important;
    border-color: #1f7a45 !important;
    color: #ffffff !important;
  }

  .s-post-summary--stats-item.has-answers.has-accepted-answer .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.has-accepted-answer .s-post-summary--stats-item-unit,
  .status.answered-accepted strong,
  .status.answered-accepted .strunk {
    color: #ffffff !important;
  }

  /* "answered" (no accept) pill: green outline */
  .s-post-summary--stats-item.has-answers:not(.has-accepted-answer),
  .status.answered {
    border-color: #2b6e44 !important;
    color: #8fdc9e !important;
  }

  /* The count NUMBER inside the "answered" pill has its own
     .s-post-summary--stats-item-number rule (muted grey) that beat the
     green above, so the pill rendered a grey "1" next to a green "answer"
     — the green signal only half-applied (the accepted pill's number was
     already pinned white; this outline variant was missed). Lift the
     number back to the pill's green so the whole pill reads as one. */
  .s-post-summary--stats-item.has-answers:not(.has-accepted-answer) .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.has-answers:not(.has-accepted-answer) .s-post-summary--stats-item-unit {
    color: #8fdc9e !important;
  }

  /* The BOUNTY pill in the same stats column ("+50", "+100" — MathOverflow,
     Meta and every *.stackexchange.com list page) is a solid `--blue-500`
     #155ca2 chip that SE labels WHITE. It is a `.s-post-summary--stats-item`,
     so the muted-grey rule at the top of the file flattened the label to
     #9198a1 on that blue — 2.3:1, and the loudest "this question pays" signal
     on a list page stopped reading as one. The fill is SE's own and stays. */
  .s-post-summary--stats-item.has-bounty,
  .s-post-summary--stats-item.has-bounty .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.has-bounty .s-post-summary--stats-item-unit {
    color: #ffffff !important;
  }

  /* Filter / sort tabs (segmented controls). The GROUP has a real frame
     natively (--black-300) and is recoloured with the other borders below;
     its ITEMS carry `1px solid transparent` for layout only — the frame plus
     the filled selected chip is the whole affordance — so only their label
     colour belongs here. Giving each item a visible hairline draws a box the
     site never draws and doubles up against the group frame. */
  .s-btn-group .s-btn {
    color: #c4cdd6 !important;
  }

  .s-btn.s-btn__muted.s-btn__outlined,
  .youarehere,
  .js-filter-btn {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .s-btn-group .s-btn.is-selected,
  .s-btn-group .s-btn[aria-pressed="true"],
  .nav-tabs .youarehere {
    background-color: #20303d !important;
    color: #bfe0f7 !important;
    border-color: #2b4253 !important;
  }

  /* Secondary time-filter "subtabs" (all / year / quarter / month / week on the
     Users list, and the same control on other network pages) are bare <a> links
     wrapping an inner .s-btn--text span. SE leaves the unselected ones its
     #636b74 (~3.3:1 dark-on-dark, fails AA at this size) and marks the SELECTED
     one with blue text + a blue underline — but our blanket `.youarehere` reset
     flattened the selected accent to grey and the `.s-btn--text` rule pinned every
     label to one grey, so the selected tab lost its signal. Lift the unselected
     labels to a legible muted grey and restore the selected tab's blue accent.
     The span needs its own selector because `.s-btn--text` colours the label. */
  .subtabs a,
  .subtabs a .s-btn--text {
    color: #9198a1 !important;
  }

  .subtabs a:hover,
  .subtabs a:hover .s-btn--text {
    color: #c4cdd6 !important;
  }

  .subtabs .youarehere.is-selected,
  .subtabs .youarehere .s-btn--text {
    color: #6fb3e8 !important;
  }

  .subtabs .youarehere.is-selected {
    border-bottom-color: #5fb0e6 !important;
  }

  /* ============================================================
     Buttons
     ============================================================ */
  .s-btn__primary,
  .s-btn.s-btn__primary,
  .s-btn__primary .s-btn__inner,
  .s-btn__filled,
  .s-btn.s-btn__filled {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  /* HOVER on the filled primary CTA ("Sign up", "Ask Question", "Post Your
     Answer", "Apply filter"). This must out-rank BOTH the generic
     `.s-btn:hover` mute below it (equal specificity, declared later, so it was
     winning and turning the primary button the same dark #1c2128 as a
     secondary one — hovering "Sign up" made it indistinguishable from the
     outlined "Log in" beside it) AND the 3-class `.s-btn.s-btn__primary.ws-nowrap`
     fill near the end of this section. Hence the element-qualified arms. */
  .s-btn.s-btn__primary:hover,
  .s-btn.s-btn__filled:hover,
  a.s-btn.s-btn__primary:hover,
  a.s-btn.s-btn__filled:hover,
  button.s-btn.s-btn__primary:hover,
  button.s-btn.s-btn__filled:hover { background-color: #3b82b8 !important; color: #fff !important; }

  .s-btn,
  .s-btn__muted,
  .s-btn__outlined {
    color: #c4cdd6 !important;
  }

  .s-btn:hover,
  .s-btn__muted:hover {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* A BARE `.s-btn` — no `__muted` / `__outlined` / `__filled` / `__primary`
     modifier — is Stacks' tertiary action, link-blue text on no fill: "Cancel"
     under the questions Filter panel, "Not now" on the signup modal, "View all
     N Collectives". The base grey above is the `__muted` look, so this shape
     needs the accent back. Every modifier that carries its own ink is
     excluded, as are the topbar / modal-close / pressed shapes and anything
     stamped with an `.fc-*` utility (its ink is named on the element). The
     `:not()` chain out-weighs `.s-btn:hover`, so the hover ink is restated. */
  .s-btn:not(.s-btn__muted):not(.s-btn__outlined):not(.s-btn__filled):not(.s-btn__primary):not(.s-btn__unset):not(.s-btn__link):not(.s-btn__google):not(.s-btn__github):not(.s-btn__facebook):not(.s-btn__danger):not(.s-btn__featured):not(.is-selected):not(.s-topbar--item):not(.s-topbar--menu-btn):not(.s-modal--close):not([class*="fc-"]) {
    color: #5fb0e6 !important;
  }

  .s-btn:not(.s-btn__muted):not(.s-btn__outlined):not(.s-btn__filled):not(.s-btn__primary):not(.s-btn__unset):not(.s-btn__link):not(.s-btn__google):not(.s-btn__github):not(.s-btn__facebook):not(.s-btn__danger):not(.s-btn__featured):not(.is-selected):not(.s-topbar--item):not(.s-topbar--menu-btn):not(.s-modal--close):not([class*="fc-"]):hover {
    color: #9bd4ff !important;
  }

  /* A pressed toggle outside an `.s-btn-group` (the intro-banner disclosure on
     /beta/challenges) is filled from `--_bu-bg-selected` / `--_bu-fc-selected`
     — `--black-150` #e3e6e8 under `--black-600` ink. No `.bg-black-*` utility
     is on the element, so nothing else in this file reaches it. `__filled` and
     `__primary` carry their own selected tokens and keep the brand blue; the
     hover arm is needed because the mute above would otherwise strip the
     pressed fill on pointer-over, which Stacks itself never does. */
  .s-btn.is-selected:not(.s-btn__filled):not(.s-btn__primary),
  .s-btn.is-selected:not(.s-btn__filled):not(.s-btn__primary):hover,
  .s-btn--radio:checked + .s-btn {
    background-color: #20303d !important;
    color: #bfe0f7 !important;
  }

  .s-btn__outlined {
    border-color: #2d333b !important;
  }

  /* Stacks is BEM: every `.s-btn__<variant>` only sets custom properties
     (--_bu-fc, --_bu-filled-bg) that the base `.s-btn` rule consumes. Our
     base-class `!important` above therefore beats EVERY variant and
     flattens them all to one muted grey. Restore each variant's semantics
     with a 2-class selector (higher specificity than the base rule). */

  /* OAuth buttons are brand assets (SE's own dark theme keeps them too):
     white Google, near-black GitHub, blue Facebook. Our `.s-btn` grey left
     "Log in with Google" at ~1.8:1 on its white pill. Restore native text. */
  .s-btn.s-btn__google {
    color: #3b4045 !important;
  }

  .s-btn.s-btn__github,
  .s-btn.s-btn__facebook {
    color: #ffffff !important;
  }

  /* Their hover arms too. `.s-btn:hover` is 1 class + 1 pseudo — the same
     weight as the `.s-btn.s-btn__google` rest rule above, which is declared
     later and therefore keeps the dark ink while the hover paints the pill
     #1c2128: hovering "Sign up with Google" dropped the label to ~1.2:1 on the
     signup modal every page ships. SE gives each variant its own hover fill;
     restore those. */
  .s-btn.s-btn__google:hover {
    background-color: #f1f2f3 !important;
    color: #3b4045 !important;
  }

  .s-btn.s-btn__github:hover {
    background-color: #0c0d0e !important;
    color: #ffffff !important;
  }

  .s-btn.s-btn__facebook:hover {
    background-color: #314a86 !important;
    color: #ffffff !important;
  }

  /* Link-styled buttons ("Copy link" in the share popover, "Search help")
     are blue links natively. The post-menu ones (Share / Follow) are
     deliberately muted grey — keep those muted. */
  .s-btn.s-btn__link {
    color: #5fb0e6 !important;
  }

  /* The post menu mixes `.s-btn__link` buttons with bare anchors — the /tour
     mock post's "edit" is one, on SE's raw --black-400 (#636b74, 3.0:1). Both
     shapes are the same control row and must read the same. */
  .js-post-menu .s-btn.s-btn__link,
  .post-menu .s-btn.s-btn__link,
  .post-menu a.c-default,
  .js-post-menu a.c-default {
    color: #9198a1 !important;
  }

  /* …except "Copy link", which lives INSIDE the share popover the post menu owns,
     so the mute above swallowed it too: it rendered grey right next to the blue
     "CC BY-SA 4.0" link in the same row, the only two link-styled controls there.
     It is an action, and SE paints it the link blue — put it back. */
  .js-post-menu .s-btn.s-btn__link.js-copy-link-btn,
  .post-menu .s-btn.s-btn__link.js-copy-link-btn {
    color: #5fb0e6 !important;
  }

  /* …and its neighbour, the "CC BY-SA 4.0" licence link in the same row, which
     is an <a>, not a `.s-btn`, so none of the rules above reach it. It keeps
     SE's raw `--blue-400` #1b75d0 straight from `.s-anchors__default` — 3.4:1
     on the #1c2128 popover, and visibly duller than the accent "Copy link"
     18px to its left. Two links, same row, two blues. */
  .share-sheet-popover a.js-license,
  .s-popover a.js-license {
    color: #5fb0e6 !important;
  }

  /* Stacks also link-styles a button by adding `.s-link` ALONGSIDE the button
     classes — SE's link colour then wins natively, but our 1-class
     `.s-btn__muted` / `.s-btn` rules out-rank it and paint the control body
     grey. The "Add a comment" control under every post is the live case: it
     moved from `.js-add-link` (which this file already accents) to
     `button.s-link.s-btn__muted.s-btn__outlined.comments-link`, so it stopped
     reading as an action at all. Match on the `.s-link` pairing, not the one
     renamed class, so the whole shape is covered. */
  .s-link.s-btn,
  .s-link.s-btn__muted,
  .s-link.s-btn__outlined,
  .comments-link {
    color: #5fb0e6 !important;
  }

  /* Outlined CTAs ("Log in", "Ask question") are the accent colour; only
     the muted variant is grey. */
  .s-btn.s-btn__outlined {
    color: #5fb0e6 !important;
    border-color: #3b82b8 !important;
  }

  .s-btn.s-btn__outlined.s-btn__muted {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* An outlined button that is TOGGLED OPEN (the questions-list "Filter"
     button while its panel is showing) gets `.is-selected`, which SE fills
     with a pale blue (#92c2f2). Our outlined-CTA accent then painted a
     light-blue label on that light-blue fill (~1.4:1 — the word "Filter"
     all but vanished). Give the open state the same dark selected-chip
     treatment the segmented sort tabs already use. */
  .s-btn.s-btn__outlined.is-selected,
  .s-btn.s-btn__outlined.is-selected:hover {
    background-color: #20303d !important;
    color: #bfe0f7 !important;
    border-color: #2b4253 !important;
  }

  /* Destructive + neutral-filled variants */
  .s-btn.s-btn__danger {
    color: #f0a8a8 !important;
  }

  .s-btn.s-btn__danger.s-btn__filled {
    background-color: #8b2c31 !important;
    color: #ffffff !important;
    border-color: #a03a40 !important;
  }

  .s-btn.s-btn__filled.s-btn__muted {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #3d444d !important;
  }

  /* `__featured` is the last unhandled `.s-btn__<variant>`: a purple
     (--purple-400/500) promo CTA that the base `.s-btn` grey flattened like
     the rest of the family. Keep the purple identity, retoned for dark. */
  .s-btn.s-btn__featured {
    color: #a8abf2 !important;
  }

  .s-btn.s-btn__featured.s-btn__outlined {
    color: #a8abf2 !important;
    border-color: #5a5fc0 !important;
  }

  .s-btn.s-btn__featured.s-btn__filled {
    background-color: #4a4fa8 !important;
    color: #ffffff !important;
    border-color: #5a5fc0 !important;
  }

  /* The count chip inside a sort tab ("Bountied 3"). Stacks fills
     `.s-btn .s-btn--badge` from `background-color: currentColor`, and Stack
     Overflow additionally stamps the element with the `.bg-blue-500` utility
     — which our announcement-banner retone of `.bg-blue-*` swallowed, leaving
     a near-invisible #14222e chip. The legacy `.bounty-indicator*` chip that
     renders the SAME control on the other network sites was untouched and
     stayed brand blue, so one component had two looks. Pin both to the
     theme's accent fill. `.bounty-indicator-tab.flagbg` (red) is 2 classes
     and !important in SE's own sheet, so it still wins. */
  .s-btn-group .s-btn .s-btn--badge,
  .s-btn--badge.bg-blue-500,
  .s-btn--badge.bg-blue-400,
  .s-btn--badge.bg-blue-600,
  .bounty-indicator,
  .bounty-indicator-tab {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
  }

  /* "Ask Question" big button */
  .ask-question-btn, .s-btn.s-btn__primary.ws-nowrap {
    background-color: #2f6f9f !important;
  }

  /* ============================================================
     Notices, callouts, badges
     ============================================================ */
  .s-notice,
  .s-notice__info {
    background-color: #14222e !important;
    border-color: #234055 !important;
    color: #bcd3e6 !important;
  }

  .s-notice__warning,
  .s-notice.s-notice__warning {
    background-color: #2a2114 !important;
    border-color: #4a3a1c !important;
    color: #e8c98a !important;
  }

  .s-notice__danger,
  .s-notice__important {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  .s-notice__success {
    background-color: #16221a !important;
    border-color: #25402d !important;
    color: #aee0bb !important;
  }

  /* Legacy ".val-message" validation banners (login / ask-gate / form
     errors) predate the Stacks .s-notice system: SE paints .val-info a
     cream #faecc6, .val-warning/.val-error a pale yellow/red — all with
     near-black text. Their cream blue-channel (198) sneaks under the
     audit's >200 near-white threshold, so a bg-color scan passes clean
     while the panel glares light. Retone to tinted-dark with light text. */
  .val-message,
  .val-message.val-info {
    background-color: #221d14 !important;
    border-color: #3a3320 !important;
    color: #e8c98a !important;
  }

  .val-message.val-warning {
    background-color: #2a2114 !important;
    border-color: #4a3a1c !important;
    color: #e8c98a !important;
  }

  .val-message.val-error {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  .val-message a { color: #5fb0e6 !important; }

  .s-badge,
  .s-badge__bounty {
    background-color: #20303d !important;
    color: #8cc6f0 !important;
    border-color: #2b4253 !important;
  }

  /* …and the same BEM trap as the buttons: every `.s-badge__<variant>` only
     sets --_ba-bg / --_ba-fc custom properties, so the base rule above
     flattened the WHOLE family — the green "accepted answers" pill on a
     user profile, the blue bounty pill, the gold/silver/bronze metals and
     the danger/warning/staff tints all rendered as one identical blue chip.
     Restore each variant with a 2-class selector, retoned for dark. */
  .s-badge.s-badge__answered {
    background-color: #1f7a45 !important;
    color: #ffffff !important;
    border-color: #1f7a45 !important;
  }

  .s-badge.s-badge__bounty {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  .s-badge.s-badge__important {
    background-color: #8b2c31 !important;
    color: #ffffff !important;
    border-color: #8b2c31 !important;
  }

  .s-badge.s-badge__rep {
    background-color: transparent !important;
    color: #8fdc9e !important;
    border-color: #2b6e44 !important;
  }

  .s-badge.s-badge__rep-down {
    background-color: transparent !important;
    color: #f0a8a8 !important;
    border-color: #5a2a2c !important;
  }

  .s-badge.s-badge__gold {
    background-color: #2a2417 !important;
    color: #e8c98a !important;
    border-color: #6b5518 !important;
  }

  .s-badge.s-badge__silver {
    background-color: #24282c !important;
    color: #c0c6cc !important;
    border-color: #5a6068 !important;
  }

  .s-badge.s-badge__bronze {
    background-color: #2a2018 !important;
    color: #d0a07a !important;
    border-color: #6b4a30 !important;
  }

  .s-badge.s-badge__danger {
    background-color: #2a1718 !important;
    color: #f0a8a8 !important;
    border-color: #5a2a2c !important;
  }

  .s-badge.s-badge__warning {
    background-color: #2a2114 !important;
    color: #e8c98a !important;
    border-color: #4a3a1c !important;
  }

  .s-badge.s-badge__staff,
  .s-badge.s-badge__admin,
  .s-badge.s-badge__moderator {
    background-color: #3a2b20 !important;
    color: #e0a878 !important;
    border-color: #5a4326 !important;
  }

  .s-badge.s-badge__new {
    background-color: #221c2e !important;
    color: #c0a8e8 !important;
    border-color: #3a2f55 !important;
  }

  /* The rest of the `.s-badge__*` family, same BEM trap. Stacks currently
     ships 22 variants; the block above named 13, so these seven still fell
     through to the base blue chip:
       __votes   a post's score pill on a profile's "Top posts" rows. SE
                 paints it WHITE with black-500 text unless it also carries
                 __answered (green) — so the blue chip read as a second
                 positive state next to the green one. Mirror SE's own
                 `:not(.s-badge__answered)` guard so the green survives, and
                 use the same neutral chip `.answer-votes` already gets.
       __muted / __muted.__filled   neutral greys (black-200 / black-500).
       __danger.__filled            red-400 fill: the 2-class __danger rule
                                    above sets background-color directly, so
                                    it beat SE's 3-class token rule and
                                    flattened the solid red to the tint.
       __info    blue-200 info chip; explicit so it does not drift.
       __ai      orange-500 uppercase label, border = the text colour.
       __bot     black-300 outline (the "Community Bot" author chip).
     Each keeps the size/shape modifiers (__sm, __xs) untouched. */
  .s-badge.s-badge__votes:not(.s-badge__answered) {
    background-color: #20262d !important;
    color: #9198a1 !important;
    border-color: #2d333b !important;
  }

  .s-badge.s-badge__muted {
    background-color: #20262d !important;
    color: #9198a1 !important;
    border-color: #3d444d !important;
  }

  .s-badge.s-badge__muted.s-badge__filled {
    background-color: #3d444d !important;
    color: #ffffff !important;
    border-color: #3d444d !important;
  }

  .s-badge.s-badge__danger.s-badge__filled {
    background-color: #a03a40 !important;
    color: #ffffff !important;
    border-color: #a03a40 !important;
  }

  .s-badge.s-badge__info {
    background-color: #14222e !important;
    color: #8cc6f0 !important;
    border-color: #234055 !important;
  }

  .s-badge.s-badge__ai {
    background-color: #2a2114 !important;
    color: #e0913f !important;
    border-color: #e0913f !important;
  }

  .s-badge.s-badge__bot {
    background-color: #20262d !important;
    color: #c4cdd6 !important;
    border-color: #3d444d !important;
  }

  /* `.s-label--status` — the small rounded status pill beside a heading
     ("Open to all users", "Last message 2m ago", "Beta"). It paints from
     per-component tokens only (`--_la-status-bg` / `--_la-status-fc`), so no
     `.bg-*` / `.fc-*` remap reaches it and every variant shipped as a light
     pill with dark ink. Redefining the tokens keeps the variant semantics
     (neutral / blue beta / green new / red required) and the pill geometry. */
  .s-label--status {
    --_la-status-bg: #262c33 !important;
    --_la-status-fc: #c4cdd6 !important;
  }

  .s-label--status.s-label--status__beta {
    --_la-status-bg: #14222e !important;
    --_la-status-fc: #7cb7dd !important;
  }

  .s-label--status.s-label--status__new {
    --_la-status-bg: #14261c !important;
    --_la-status-fc: #8fdc9e !important;
  }

  .s-label--status.s-label--status__required {
    --_la-status-bg: #2d1a1a !important;
    --_la-status-fc: #f0a0a0 !important;
  }

  /* reputation / badge counts on user cards */
  .reputation-score, .user-info .reputation-score {
    color: #c4cdd6 !important;
  }

  /* A badge PILL that is also a link (`a.badge` — the Help Center's
     Bronze/Silver/Gold explainers, the per-badge chips on a profile) sits on
     SE's own `--black-500` #3b4045 fill, so the page accent lands at 4.4:1 on
     it. The fill is a component surface we do not darken; brighten the label
     instead so the pill still reads as a link and clears AA at 12px. The
     `#sidebar` arm is required: the id-scoped `#sidebar a` accent above
     out-specifies a bare `a.badge`, and the Help Center explainers live there. */
  a.badge,
  #sidebar a.badge {
    color: #7cc0ea !important;
  }

  .badgecount { color: #c4cdd6 !important; }
  .badge1, .badgecount .gold { color: #e8c98a !important; }
  .badge2, .badgecount .silver { color: #c0c6cc !important; }
  .badge3, .badgecount .bronze { color: #d0a07a !important; }

  /* user cards (signature blocks) */
  .post-signature,
  .user-info {
    color: #c4cdd6 !important;
  }

  /* Avatar TILES. `.s-avatar` fills its box from `--_av-bg: var(--_white-static)`
     — pure white. A gravatar covers the box exactly so the fill never shows,
     but SE's default avatar (`Content/Img/user.svg`) is a #6a737c silhouette
     on a TRANSPARENT canvas: every user without a gravatar, plus deleted and
     anonymous users, renders a solid white rounded square. Retone the token
     (not `background-color`) so the rounded-corner geometry and the size
     modifiers 16/24/32/48/64/96/128 all keep working. */
  .s-avatar {
    --_av-bg: #262c33 !important;
  }

  /* In the legacy signature block the display name is a BARE <a> (no class)
     inside .user-details — a different element from the Stacks
     `.s-user-card--link` restored above, and it was being painted the same
     muted grey as the rep/badge metadata around it. It is the post author's
     link: give it the accent. */
  .user-details a,
  .post-signature .user-details a {
    color: #5fb0e6 !important;
  }

  .user-details a:hover,
  .post-signature .user-details a:hover {
    color: #9bd4ff !important;
  }

  /* The moderator diamond beside a username is a `<span>`, so it never picked up
     the anchor accent — it takes SE's raw `--theme-link-color` (#1b75d0 on the
     blue sites, 3.3:1 on the page base). It is the one place the un-lifted link
     colour still leaks. Match the accent the names around it already use. */
  .mod-flair,
  span.mod-flair {
    color: #5fb0e6 !important;
  }

  /* SE tints ONLY the post OWNER's signature card (`.post-signature.owner`,
     #edf5fd) — that tint is the sole marker of which of the "edited by" /
     "asked by" cards belongs to the author. Tinting `.user-info` too painted
     every signature on the page the same blue and erased the signal. */
  .post-signature.owner,
  .post-signature.owner .user-info {
    background-color: #16202c !important;
    border-radius: 5px;
  }

  /* The "New contributor" indicator SE stamps under a new user's post signature
     (`.new-contributor-indicator`) carries a light-blue #cde8f3 fill with near-black
     `.fc-black-500` text — our text-lift makes the label grey-on-light-blue (near
     invisible) and the whole pill glares light on dark. It is 200x30 so it slips the
     audit height filter. Retone to the same tinted-dark-blue as the info notices; the
     hand glyph beside the label rides on `.fc-black-500` too and lifts with it. */
  .new-contributor-indicator {
    background-color: #14222e !important;
    color: #bcd3e6 !important;
  }

  /* ============================================================
     User profiles
     ============================================================ */
  .profile-card,
  .js-profile-card,
  .user-show-new .bg-white,
  #user-card,
  .userprofile {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .profile-header,
  .user-header {
    background-color: transparent !important;
  }

  /* Collectives / Communities cards: the collective NAME label
     (.subcommunity-topic-avatar .fs-body2) keeps SE's near-black
     #0c0d0e and renders dark-on-dark on the card. Lift it. */
  .subcommunity-topic-avatar .fs-body2,
  .subcommunity-topic-avatar .fs-body1,
  a.s-link__inherit .subcommunity-topic-avatar div {
    color: #e6edf3 !important;
  }

  /* Reputation sparkline (`.profile-cards--graph`). Its horizontal gridlines
     are a repeating-linear-gradient BACKGROUND-IMAGE in `var(--black-200)`
     #e3e6e8 over a transparent background-COLOR, so a bg-color scan reads the
     node as clean while three near-white bands stripe the card. Repaint the
     bands only — the geometry (`background-position: 0 -4px`) is a separate
     longhand we do not touch, and the green `.line` data stroke is untouched. */
  .profile-cards--graph,
  div.profile-cards--graph,
  .profile-cards--graph.js-reputation-graph {
    background-image: repeating-linear-gradient(0deg, transparent, transparent 13px, #2d333b -13px, #2d333b 21px) !important;
  }

  /* Progress bars. The TRACK is `--_pr-bg: var(--black-300)` #babfc5 — a
     light-grey rail that shows wherever the bar is not filled ("Next tag
     badge" on a profile, every privilege row on /help/privileges, where an
     anonymous visitor's bar is ~0% and the whole rail is bare). Darken the
     track token only; `--_pr-bar-bg` (the green #18864b fill) is untouched, so
     the filled/empty split still reads. */
  .s-progress {
    --_pr-bg: #2d333b !important;
  }

  /* Badge-progress pills (`.s-progress__badge`, "Next badge / Instructor").
     Each medal variant fills the bar with a LIGHT metal tint —
     --silver-100 #f2f2f2, --gold-100 #ffeec2, --bronze-100 #f3e8de — while the
     label is `var(--fc-dark)` #0c0d0e absolutely positioned across the FULL
     width. On dark that is a near-white pill for the filled part and
     black-on-dark for the remainder. Retone each metal to a dark member of its
     own hue family so the silver/gold/bronze signal survives, and lift the
     label so it reads over both halves. `--_pr-label-bc` (the metal-400 ring)
     is already dark enough to keep. */
  .s-progress.s-progress__silver {
    --_pr-bar-bg: #4b5057 !important;
  }

  .s-progress.s-progress__gold {
    --_pr-bar-bg: #6b5713 !important;
  }

  .s-progress.s-progress__bronze {
    --_pr-bar-bg: #5f4531 !important;
  }

  /* The privilege variant fills with `var(--green-200)` hsl(148,35%,88%), a
     near-white mint — same shape as the metals. Only rendered for signed-in
     users, so it is fixed by the same token path rather than verified live. */
  .s-progress.s-progress__privilege {
    --_pr-bar-bg: #1f7a45 !important;
  }

  .s-progress__badge .s-progress--label,
  .s-progress__privilege .s-progress--label {
    color: #e6edf3 !important;
  }

  /* The "Graph" view of a profile's Reputation tab
     (`?tab=reputation&sort=graph`) draws two Highcharts SVGs — `#detail-graph`
     and the `#master-graph` navigator under it. Highcharts writes its colours
     as ATTRIBUTES and INLINE `style="fill:…"`, so nothing but a `fill:` /
     `stroke:` rule reaches them:
       - the detail chart's plate is a class-less `<rect fill="var(--white)">`,
         886x300 of pure white — the largest light surface left anywhere under
         /users/;
       - the tooltip box takes the same `var(--white)` with near-black text, and
         exists in the DOM only while a bar is hovered;
       - axis lines and ticks are --black-300 / --black-350 / #C0D0E0;
       - every bar carries a #FFFFFF separator stroke.
     The `--green-500` gains and `--red-400` losses ARE the data series and stay
     exactly as SE painted them, and `.highcharts-tracker` rects are the
     invisible hit targets (`rgb(192,192,192)` at fill-opacity ~0) — neither is
     touched. */
  .highcharts-container rect[fill="var(--white)"] {
    fill: #1c2128 !important;
  }

  .highcharts-container g.highcharts-series rect[stroke="#FFFFFF"] {
    stroke: #1c2128 !important;
  }

  .highcharts-container path[stroke="#C0D0E0"],
  .highcharts-container path[stroke="var(--black-300)"],
  .highcharts-container path[stroke="var(--black-350)"] {
    stroke: #2d333b !important;
  }

  /* Each `<text>` carries an inline `style` that sets BOTH `fill` and `color`;
     only `fill` paints an SVG glyph, but pin `color` too — Highcharts switches
     the same label to an HTML node under `useHTML`, where `color` is what
     renders (see the tooltip below). */
  .highcharts-container g.highcharts-axis text,
  .highcharts-container g.highcharts-axis tspan {
    fill: #9198a1 !important;
    color: #9198a1 !important;
  }

  /* The axis TITLE ("reputation per day") is a direct child of the <svg> and
     takes --blue-500 #155ca2 — 2.4:1 once the plate is dark. Lift to the link
     accent so it still reads as SE's blue label. */
  .highcharts-container > svg > text,
  .highcharts-container > svg > text tspan {
    fill: #5fb0e6 !important;
    color: #5fb0e6 !important;
  }

  .highcharts-container g.highcharts-tooltip text,
  .highcharts-container g.highcharts-tooltip tspan {
    fill: #e6edf3 !important;
    color: #e6edf3 !important;
  }

  /* …and the tooltip's TEXT is not SVG at all: Highcharts renders it with
     `useHTML`, as `<span>`s absolutely positioned over the chart, carrying
     `color: var(--black-600)` #0c0d0e. Inside the now-dark box that is
     dark-on-dark, and no `fill:` rule can reach an HTML node. */
  .highcharts-container > span,
  .highcharts-container > span span,
  .highcharts-container > span strong {
    color: #e6edf3 !important;
  }

  /* The series label ("rep:") is the span right after the <br> and takes the
     series colour --green-500 #0e6235 (1.9:1 on the dark box). Keep it green,
     at the theme's readable green. */
  .highcharts-container > span > br + span {
    color: #3fb950 !important;
  }

  /* ============================================================
     Tag pages
     ============================================================ */
  .tagged-questions,
  .tag-list .grid--cell,
  .js-tag-cell,
  .s-card.js-tag-cell {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* ============================================================
     /tour — the "welcome" walkthrough
     ------------------------------------------------------------
     Every network site serves it, it is linked from the footer and the
     top-bar help menu, and it is the only page family built from the
     `.about-page .new-about-content-page` markup in `secondary.css`.
     None of the Stacks card rules reach it: it stages a mock question in
     `var(--white)` panels, so the theme's ink lift rendered the whole
     walkthrough light-grey-on-white (~1.6:1), and its section headings
     take `--black-600` behind a 3-class `!important` that out-ranks the
     network-wide h1-h6 lift, leaving them 1.1:1 on the dark base.
     ============================================================ */
  .qa-block,
  .content-block,
  .on-topic-examples,
  .off-topic-examples,
  .user-info-rep {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: none !important;
  }

  .about-page .new-about-content-page h2.about-title {
    color: #e6edf3 !important;
  }

  /* The mock post fades out under a white-to-transparent gradient that
     stands in for "there is more text below". Its background-COLOR is
     never set, so no surface audit sees it; on dark it is a bright band
     across the foot of the example. */
  .about-post-body-gradient {
    background: linear-gradient(to top, #1c2128 15%, rgba(28, 33, 40, 0)) !important;
  }

  .new-about-content-page .user-details,
  .new-about-content-page .rep-block,
  .new-about-content-page .comments,
  .new-about-content-page .rep-up-off {
    color: #9198a1 !important;
  }

  .new-about-content-page .rep-up {
    color: #3fb950 !important;
  }

  .new-about-content-page hr {
    background-color: #262c33 !important;
  }

  /* ============================================================
     Search results page
     ============================================================ */
  .search-results,
  .js-search-results,
  #search-tab-questions,
  .search-result {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .search-results .question-summary {
    border-bottom: 1px solid #20262d !important;
  }

  /* search hint sidebar */
  .search-hints, .advanced-help {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* ============================================================
     Network home (stackexchange.com) — bespoke layout
     ------------------------------------------------------------
     The network landing page mixes the shared Stacks components
     with its own bespoke markup (#question-list hot rows,
     #sideBar widgets, .featured-site card, the legacy pager),
     which none of the Stacks class rules above reach. Its Stacks
     half is covered by the utility remaps at the top of this file
     — `.fc-black` in particular, which paints nearly every label
     on this page and on no other. The hooks below cover the rest.
     Several of them (.hero-box, .navMain, .subheader, .siteHeader
     h1, .sb-siteName, .stats-label, .module .heading) match nothing
     on the current page set and are kept only as a fallback for
     network pages still serving the older markup.
     ============================================================ */
  /* The network home wordmark is an unclassed <h1> under
     header.siteHeader carrying a CDN background-image logo (dark
     "Stack" + blue "Exchange", baked for the white site). The dark
     half vanishes on our dark header, and it's neither an <img> (the
     logo-invert rule above misses it) nor DOM text (audit-blind).
     Apply the same luminance invert + hue-rotate the img logos use so
     "Stack" lifts to light while the blue brand hue is preserved. */
  header.siteHeader .contentWrapper h1,
  .siteHeader h1 {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  .hero-box {
    background-color: #16202c !important;
    border-color: #234055 !important;
  }

  .hero-box .blurb,
  .hero-box .blurb em,
  .hero-box .blurb span {
    color: #c4cdd6 !important;
  }

  /* hot / real-time question rows: white #f0f0f0 divider -> dark. The row
     ALSO carries `box-shadow: 0 1px 0 #fff` — a pure-white 1px rule under
     every row that no background / border / gradient audit bucket can see.
     Kill the shadow; the border-color above is the visible divider. */
  #question-list .question-container,
  .question-container {
    border-color: #262c33 !important;
    box-shadow: none !important;
  }

  /* main nav (All Sites / Top 400 Users / Digests): dark navy -> accent */
  .navMain a,
  .contentWrapper .navMain a {
    color: #6fb3e8 !important;
  }

  /* sidebar module headings ("Today's Featured Site", "Top Network
     Askers") + subheader tab label: near-black #444 on dark -> light */
  #sideBar .module .heading,
  .featured-sidebar .heading,
  .users-sidebar .heading,
  .module .heading {
    color: #e6edf3 !important;
  }

  /* featured-site detail text, stat labels and the per-asker site
     names (span.sb-siteName): all near-black #444 -> muted grey */
  .featured-site .site-details,
  .featured-site .stats-label,
  .stats-label,
  .sb-siteName,
  .userDetails .sb-siteName {
    color: #9198a1 !important;
  }

  /* inactive "real-time" tab (#666) vs active "hot" tab */
  .subheader .tabs a {
    color: #9198a1 !important;
  }
  /* Active "hot" tab. SE marks it with its brand red (#f35d5f text + a 2px
     red underline). Our blanket `.youarehere { border-color }` reset in the
     filter/sort-tab block flattened the underline to a dark grey and the
     text to white — the selected tab lost its accent entirely. Restore it;
     the red reads ~5.6:1 on the dark base. */
  .subheader .tabs a.youarehere,
  .subheader .tabs a.selected {
    color: #f35d5f !important;
    border-bottom-color: #f35d5f !important;
  }

  /* legacy light frames: subheader underline (#e5e5e5), the featured-
     site card (#e8edee 2px) and the pager page-number chips (#d2d2d2) */
  .subheader,
  #mainArea .subheader {
    border-color: #262c33 !important;
  }

  #sideBar .module.featured-sidebar .featured-site,
  .featured-site {
    border-color: #2d333b !important;
  }

  /* The "Featured" tag above the featured-site name is a <span> with an INLINE
     `background:#f1edfc` — a near-white lavender chip, too small for the
     light-surface audit's size floor and unreachable by any class hook. Its ink
     comes from the `.fc-purple-500` on the parent <h2>, so the two must move
     together: lifting that scale for the dark page without darkening this chip
     would put light purple on light lavender. */
  .featured-site h2 span,
  .featured-site h2 > span[style] {
    background-color: #2b2545 !important;
    background-image: none !important;
    color: #c7b3f5 !important;
  }

  /* The hub's /leagues page ("Top 400 Users"). Its explainer aside is a
     cornsilk `#fff8dc` panel with #444 body copy — the only bright surface
     left on the network hub — and each site row is separated by a #f0f0f0
     rule that shows as a bright line on dark. The per-site `.site-bubble`
     tiles carry each community's own brand colour and are left alone. */
  .module.newuser {
    background-color: #221d14 !important;
    border-color: #3a3320 !important;
    color: #e8d4a0 !important;
  }

  .module.newuser strong,
  .module.newuser b {
    color: #f0e2bd !important;
  }

  .league-container {
    border-bottom-color: #262c33 !important;
  }

  /* Legacy pager / page-sizer chips ("2 3 4 next", "15 30 50 per page").
     SE paints each non-current chip with a white-to-grey bg-IMAGE gradient
     (linear-gradient(#fff, #e7e7e7)) while its background-COLOR stays
     transparent — so a bg-color audit passes clean while the chips glare as
     white pills on the dark home. Kill the gradient and darken the fill;
     the .current chip keeps SE's red brand gradient (readable light text). */
  #question-list .page-numbers:not(.current),
  #question-list .page-sizer .page-numbers:not(.current),
  #question-list .pager .page-numbers:not(.current),
  .pager .page-numbers:not(.current),
  .page-sizer .page-numbers:not(.current) {
    background-image: none !important;
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  #question-list .page-numbers:not(.current):hover,
  .pager .page-numbers:not(.current):hover,
  .page-sizer .page-numbers:not(.current):hover {
    background-color: #222831 !important;
    color: #e6edf3 !important;
  }

  /* current page/size chip: keep the site's red pill but pin the text light */
  #question-list .page-numbers.current,
  .pager .page-numbers.current,
  .page-sizer .page-numbers.current {
    color: #ffffff !important;
  }

  /* ============================================================
     Footer
     ============================================================ */
  #footer,
  .site-footer,
  .site-footer--copyright,
  .footerwrap {
    background-color: #0d1117 !important;
    color: #9198a1 !important;
    border-top: 1px solid #262c33 !important;
  }

  #footer a, .site-footer a { color: #8aa6bb !important; }
  #footer .site-footer--categories-item-link { color: #9198a1 !important; }
  /* `.fc-white` is Stacks' "paint this white" utility. It sits on glyphs
     that live ON brand fills (the purple AI-Assist / Agents / Chat discs in
     the left nav, the announcement-banner links). A blanket override dimmed
     every one of them to grey on saturated colour. Scope the dimming to the
     footer, where .fc-white is plain text on our dark footer. */
  .site-footer--nav-link,
  #footer .fc-white,
  .site-footer .fc-white {
    color: #c4cdd6 !important;
  }

  /* The network-home (stackexchange.com) footer "Cookie Settings" control is a
     bare <button> that SE never gave the Stacks `.s-btn` reset — on the regular
     network sites the reset applies (transparent, borderless), but on the hub it
     falls back to the UA button appearance, which under our forced
     color-scheme:dark renders a grey #6b6b6b fill with a 2px white border: a
     glaring light pill among the plain footer links. Flatten it to a transparent
     control with a subtle dark outline so it sits with the other footer links.
     Scoped to the consent footer id so the correctly-styled network-site button
     is untouched. */
  #consent-footer-link button,
  #consent-footer-link .s-btn__link {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }

  /* On the Q&A sites the same control IS a `.s-btn__link`, so the network-wide
     link-button accent painted it blue while "Cookie Policy" / "Privacy Policy"
     beside it stayed grey. SE draws no distinction between them — all four are
     one footer ink — so the accent invents a hierarchy that is not there. */
  .site-footer button.s-btn__link,
  #footer button.s-btn__link {
    color: #8aa6bb !important;
  }

  /* ============================================================
     Modals / popovers / dropdowns (opaque, no bleed-through)
     ============================================================ */
  .s-modal--dialog,
  .s-popover,
  .popup,
  .s-popover .s-popover--arrow,
  .js-popup,
  .topbar-dialog,
  .modal-content,
  .js-inbox-button + .topbar-dialog,
  .s-anchors.s-anchors__default {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Stacks colours the modal's two inner regions on the REGION, not on the
     dialog: `.s-modal--header` is black-800 and `.s-modal--body` is black-500
     #3b4045. Children that carry an `.fc-*` utility get lifted by the text
     block above, but an unclassed `<p>` inherits the region colour and lands
     at ~2:1 on the dark dialog. Live case, reachable logged-out: clicking a
     vote arrow opens the "Hang on, you can't upvote just yet." modal, whose
     whole explanatory paragraph is unclassed. Colour the regions themselves. */
  .s-modal--header,
  .s-modal--title {
    color: #e6edf3 !important;
  }

  .s-modal--body,
  .s-modal--subtitle,
  .s-modal--footer {
    color: #c4cdd6 !important;
  }

  /* The dismiss control of that same modal keeps SE's `--black-150` #f1f2f3 chip
     (SE's rule out-ranks the `.s-btn` surface) while the network-wide text lift
     takes its glyph from the native #3b4045 to #c4cdd6 — a 1.2:1 ✕ nobody can
     see. The sibling close on the signup modal carries `.s-btn__muted` and is
     already dark, so darkening the chip also makes the two match. */
  button.s-btn.s-modal--close {
    background-color: #1c2128 !important;
  }

  button.s-btn.s-modal--close svg,
  button.s-btn.s-modal--close .svg-icon {
    color: #c4cdd6 !important;
  }

  button.s-btn.s-modal--close:hover {
    background-color: #262c33 !important;
  }

  /* The signup modal's "OR" separator draws its two rules as `h1::before` /
     `::after` borders straight off `--black-225` (#d6d9dc) — two near-white
     hairlines the full width of the dialog, and the widest bright thing on the
     page. Pseudo-elements are invisible to any element-background scan, and the
     modal is `aria-hidden` until a guest opens it. Its class is a Svelte hash,
     so key off the modal + heading instead; an `h1::before` with no `content`
     renders nothing, so the other dialogs are unaffected. */
  .s-modal h1::before,
  .s-modal h1::after,
  .s-modal--dialog h1::before,
  .s-modal--dialog h1::after {
    border-color: #2d333b !important;
  }

  .s-popover::before, .s-popover::after,
  .s-popover .s-popover--arrow::before,
  .s-popover .s-popover--arrow::after {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The TAG HOVER-CARD (`.tag-popup`, the 390x237 panel with the tag excerpt,
     watcher counts and the Watch/Ignore buttons). It is NOT a `.s-popover` —
     it is a legacy `.magic-popup` whose surface is a plain `.-container` child
     painted `background-color: var(--white)` with a `--black-300` border, and
     its pointer is a rotated 12px `.-arrow::before` square carrying the same
     white fill. Nothing in the Stacks popover block above matches either.
     It mounts on hover only, so no load-time scan sees it, and it appears on
     every page that renders a `.post-tag` — question, list, tags, profile,
     network-wide. Left alone it is the single largest white surface the theme
     ships, and the text lift then puts our light ink on it (the tag name and
     excerpt render near-invisible). SE ships its own `body.theme-dark` variant
     of both rules, which anonymous visitors never get. */
  .tag-popup .-container {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .tag-popup .-arrow::before {
    background: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* the top bar inbox / achievements / network dropdown panes */
  .topbar-dialog .header,
  .topbar-dialog .modal-content,
  .siteSwitcher-dialog .header {
    background-color: #20262d !important;
    color: #e6edf3 !important;
  }

  .topbar-dialog .item:hover,
  .siteSwitcher-dialog .child-site:hover {
    background-color: #222831 !important;
  }

  /* Topbar help / inbox / achievements dropdowns: their list-item
     rows carry an UNCLASSED border-bottom: 1px #f1f2f3 (white) that
     renders as glaring white divider lines on dark. Recolor every
     row divider inside these dialogs. */
  .topbar-dialog .modal-content li,
  .topbar-dialog .modal-content ul li,
  #topbar-help-dialog .modal-content li,
  .topbar-dialog .modal-content .header,
  .siteSwitcher-dialog .modal-content li {
    border-color: #262c33 !important;
  }

  /* The help dropdown's footer row ("About Us") is a featured item SE paints
     a light #e3e6e8 highlight — a glaring light panel at the bottom of the
     otherwise-dark help menu, only present while the dropdown is open. The
     row is unclassed (no state hook), so darken every help-dialog li and
     re-elevate the featured footer item with `:last-child`. */
  #topbar-help-dialog .modal-content ul li {
    background-color: transparent !important;
  }

  #topbar-help-dialog .modal-content ul li:last-child {
    background-color: #20262d !important;
  }

  /* The topbar dropdown rows' SECONDARY line (`.item-summary` — "Start here
     for a quick overview of the site" under Tour, and the sibling blurbs
     under Help Center / Meta / About Us). SE paints it from the raw
     var(--black-500) token, not an `.fc-black-*` utility, so it stays
     #3b4045 at 1.46:1 on the dark pane — the whole explanatory half of the
     help menu is unreadable. Only reachable with the dropdown OPEN. */
  .item-summary,
  .topbar-dialog .item-summary,
  #topbar-help-dialog .item-summary {
    color: #9198a1 !important;
  }

  /* Site-switcher community blurbs ("For 3D printing enthusiasts"). Unclassed
     <p class="site-desc"> on SE's #636b74 — 2.82:1 on the switcher pane. */
  .site-desc,
  p.site-desc,
  .siteSwitcher-dialog .site-desc {
    color: #9198a1 !important;
  }

  /* ============================================================
     Stacks `.s-menu` dropdown menus (`.s-block-link` rows)
     ------------------------------------------------------------
     The component every network flyout is built from: the questions-list
     "More" sort popover, the user-page "Profiles" flyout, post action menus.
     It is driven ENTIRELY by component custom properties, so class-level
     colour rules never reach it:
       --_bl-fc        row label      var(--black-500)  #3b4045 -> 1.5:1
       --_bl-bg        .is-selected   var(--black-150)  #f1f2f3 -> a full
                                       WHITE row with #0c0d0e text
       --_me-divider-bg  separator    var(--bc-light)   #e3e6e8 -> a bright bar
     Redefining the tokens keeps the component's own shape, hover behaviour
     and the `__right.is-selected` accent bar intact. These nodes only exist
     while the menu is OPEN, so no load-time scan can see them.
     ============================================================ */
  .s-block-link {
    --_bl-fc: #c4cdd6 !important;
    --_bl-fc-hover: #e6edf3 !important;
    --_bl-fc-visited: #c4cdd6 !important;
  }

  .s-block-link:hover {
    --_bl-bg: #222831 !important;
  }

  .s-block-link.is-selected {
    --_bl-bg: #2d333b !important;
    --_bl-fc: #e6edf3 !important;
  }

  /* An autocomplete panel marks its ACTIVE row with the `bg-black-150` utility
     instead of `.is-selected` (the homepage-wizard topic search), so the row
     takes the flat surface remap further down and lands on exactly the popover
     colour — the keyboard/first-result cue disappears. A direct fill is needed:
     the utility sets `background-color`, not `--_bl-bg`. */
  .s-block-link.bg-black-150 {
    background-color: #2d333b !important;
  }

  /* `__danger` ("Delete", destructive menu items) is a SEMANTIC variant that
     sets --_bl-fc to var(--red-400). The blanket !important above would
     out-rank it and flatten the destructive red, so restore it (lifted for
     dark) rather than letting the neutral label win. */
  .s-block-link.s-block-link__danger {
    --_bl-fc: #f85149 !important;
    --_bl-fc-hover: #ff7b72 !important;
    --_bl-fc-visited: #f85149 !important;
  }

  .s-menu {
    --_me-divider-bg: #2d333b !important;
    --_me-label-btc: #2d333b !important;
  }

  /* autocomplete / search suggestions dropdown */
  .js-search-dropdown,
  .acp-dropdown,
  .autocomplete,
  .s-popover.js-typeahead {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .acp-dropdown li:hover,
  .autocomplete li.selected {
    background-color: #222831 !important;
  }

  /* ============================================================
     OneTrust cookie / consent banner + preference center
     ------------------------------------------------------------
     SE serves the OneTrust GDPR banner to EU/anonymous visitors:
     a full white panel (#edf5fd) with near-black text + black
     pill buttons — completely unthemed and glaring on dark.
     OneTrust uses its own stable IDs/classes (not SE's Stacks
     system), so it needs a dedicated block.
     ============================================================ */
  #onetrust-banner-sdk,
  #onetrust-banner-sdk .ot-sdk-container,
  #onetrust-button-group-parent,
  #onetrust-pc-sdk,
  #ot-pc-content,
  #onetrust-pc-sdk .ot-pc-header,
  #onetrust-pc-sdk .ot-pc-footer,
  #onetrust-pc-sdk .ot-cat-item,
  #onetrust-pc-sdk #ot-pc-lst,
  #onetrust-pc-sdk .ot-accordion-layout {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  #onetrust-policy-title,
  #ot-pc-title,
  #onetrust-pc-sdk h2,
  #onetrust-pc-sdk h3,
  #onetrust-pc-sdk .ot-cat-header {
    color: #e6edf3 !important;
  }

  #onetrust-policy-text,
  #onetrust-banner-sdk #onetrust-policy-text span,
  #onetrust-banner-sdk .ot-b-addl-desc,
  #onetrust-banner-sdk .ot-dpd-desc,
  #onetrust-banner-sdk .ot-dpd-title,
  #onetrust-banner-sdk .ot-tcf2-vendor-count,
  #onetrust-banner-sdk #option-details-1,
  #onetrust-banner-sdk #option-details-1 li,
  #onetrust-banner-sdk ul li,
  #ot-pc-desc,
  #onetrust-pc-sdk p,
  #onetrust-pc-sdk li,
  #onetrust-pc-sdk .ot-cat-item p,
  #onetrust-pc-sdk label {
    color: #c4cdd6 !important;
  }

  #onetrust-banner-sdk a,
  #onetrust-banner-sdk .ot-link-btn,
  #onetrust-pc-sdk a,
  #onetrust-pc-sdk .ot-link-btn {
    color: #5fb0e6 !important;
  }

  /* primary accept / reject / save buttons -> theme blue. SE ships
     these with 3-ID + type specificity
     (#onetrust-banner-sdk #onetrust-button-group button#id), so
     mirror that exact pattern to win the cascade. */
  #onetrust-banner-sdk #onetrust-button-group button#onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-button-group button#onetrust-reject-all-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .save-preference-btn-handler {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  /* secondary "Customize settings" link-button -> readable accent.
     In the preference center the reject button carries
     `.ot-pc-refuse-all-handler` as a CLASS (no id), and SE's own OneTrust
     skin paints it `background: var(--black-150) !important` — so the
     id-only selector never matched and the button shipped as a white pill.
     Mirror SE's selector at 2-id specificity so we win. */
  #onetrust-banner-sdk #onetrust-button-group button#onetrust-pc-btn-handler,
  #onetrust-pc-sdk #ot-pc-refuse-all-handler,
  #onetrust-consent-sdk #onetrust-pc-sdk button.ot-pc-refuse-all-handler {
    background-color: transparent !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }

  /* "Always Active" status label: SE's skin colours it var(--black-600)
     (#0c0d0e) — pure dark-on-dark inside the (now dark) panel. */
  #onetrust-pc-sdk .ot-always-active,
  #onetrust-pc-sdk .ot-cat-grp .ot-always-active,
  #onetrust-pc-sdk .ot-vs-list .ot-always-active {
    color: #8fdc9e !important;
  }

  /* Category / sub-group row dividers keep OneTrust's light greys
     (#d6d9dc, #d8d8d8, #e2e2e2) and glare as bright rules on dark. */
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-cat-item,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-acc-hdr,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-subgrp-cntr,
  #onetrust-consent-sdk #onetrust-pc-sdk li.ot-subgrp {
    border-color: #2d333b !important;
  }

  /* The body a cookie category unfolds into. The `.ot-cat-item` rules above only
     reach the collapsed header strip; the panel underneath is a sibling
     `.ot-acc-grpcntr.ot-acc-txt` that OneTrust plates #f8f8f8 — ~1300px of white
     once every category is open. It is `max-height: 0` until expanded, so a
     load-time scan reports it clean; the expander is an UNCLASSED
     `<button aria-expanded>` stacked over the heading, so only clicking THAT
     button opens it. #20262d keeps it one step above the #1c2128 category rows.
     `.ot-host-info` / `.ot-ven-dets` / `.ot-acc-cntr > .ot-acc-hdr` are the same
     plate on the host-list and vendor sub-screens. */
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-acc-grpcntr.ot-acc-txt,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-acc-txt .ot-ven-dets,
  #onetrust-consent-sdk #onetrust-pc-sdk #ot-host-lst .ot-host-info,
  #onetrust-pc-sdk .ot-host-info,
  #onetrust-pc-sdk .ot-acc-cntr > .ot-acc-hdr,
  #onetrust-pc-sdk .ot-pli-hdr.ot-leg-border-color {
    background-color: #20262d !important;
    border-color: #2d333b !important;
  }

  /* The switch's own wrapper is plated (white at the category level, #f8f8f8
     inside a sub-group) purely to mask the track; transparent lets it sit on
     whichever surface it lands on. The track itself is painted below. */
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-switch.ot-toggle {
    background-color: transparent !important;
  }

  /* Search / filter chrome of the vendor sub-screen. OneTrust plates all of it
     pure white at 2-id specificity and rings the flyout with a light shadow. */
  #onetrust-consent-sdk #ot-search-cntr,
  #onetrust-consent-sdk #onetrust-pc-sdk #ot-fltr-cnt,
  #onetrust-consent-sdk #onetrust-pc-sdk #ot-anchor,
  #onetrust-pc-sdk input[type="text"] {
    background-color: #20262d !important;
    border-color: #2d333b !important;
  }

  #onetrust-pc-sdk #ot-fltr-cnt,
  #onetrust-pc-sdk #ot-anchor {
    box-shadow: 0 0 12px 2px rgba(0, 0, 0, 0.55) !important;
  }

  /* "Object to Legitimate Interest" is a two-state pill: OneTrust ships the
     resting state as a white/#4d4d4d OUTLINE button and the objected state as a
     filled one, so the dark versions must stay just as distinguishable. */
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-leg-btn-container .ot-inactive-leg-btn {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #3d444d !important;
  }

  #onetrust-consent-sdk #onetrust-pc-sdk .ot-leg-btn-container .ot-active-leg-btn {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  #onetrust-consent-sdk #onetrust-pc-sdk .ot-leg-btn-container .ot-active-leg-btn svg path {
    fill: #ffffff !important;
  }

  #onetrust-consent-sdk #onetrust-pc-sdk .ot-leg-btn-container .ot-remove-objection-handler {
    color: #5fb0e6 !important;
  }

  /* Hairlines OneTrust draws inside an expanded body and the vendor sub-screens
     (#d8d8d8 / #e2e2e2 / #e9e9e9). `.ot-ven-disc` states its rule !important at
     1-id + 3-class, so that one override needs the second id to land. */
  #onetrust-pc-sdk .ot-acc-cntr,
  #onetrust-pc-sdk .ot-acc-grpcntr .ot-subgrp-cntr,
  #onetrust-pc-sdk .ot-vnd-info-cntr,
  #onetrust-pc-sdk .ot-vnd-serv-hdr-cntr,
  #onetrust-pc-sdk .ot-vnd-item button,
  #onetrust-pc-sdk .ot-vnd-info,
  #onetrust-pc-sdk .ot-ven-dets .ot-ven-pur p[aria-level="5"],
  #onetrust-pc-sdk .ot-pgph-desc::after,
  #onetrust-pc-sdk ul li {
    border-color: #2d333b !important;
  }

  #onetrust-consent-sdk #onetrust-pc-sdk .ot-ven-dets .ot-ven-disc {
    border-top-color: #2d333b !important;
  }

  /* Labels and status spans OneTrust paints #3b4045 directly on the span, below
     the p / li / label rule above. */
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-chkbox label span,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-checkbox label span,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-sel-all-hdr span,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-li-title,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-label-status,
  #onetrust-consent-sdk #onetrust-pc-sdk #ot-pvcy-txt,
  #onetrust-consent-sdk #onetrust-pc-sdk #privacy-text,
  #onetrust-consent-sdk #onetrust-pc-sdk #modal-header {
    color: #c4cdd6 !important;
  }

  /* Global Privacy Control notice: a pale-green plate that only renders when the
     browser sends the signal. Keep the green ring and glyph, drop the plate. */
  #onetrust-banner-sdk #onetrust-policy .ot-optout-signal,
  #onetrust-pc-sdk #ot-pc-content .ot-optout-signal {
    background-color: #1b2b25 !important;
    border-color: #32ae88 !important;
    color: #c4cdd6 !important;
  }

  /* the accordion "+" expander is drawn from two dark-navy bars */
  #onetrust-pc-sdk .ot-plus-minus span {
    background-color: #9198a1 !important;
  }

  /* Each cookie category's on/off toggle. OFF is a #a7abb1 track carrying a pure
     WHITE knob (a `::before`) — three 45x25 light pills that are the brightest
     things left on the dark panel, and both too small for the light-surface
     height filter and pseudo-painted. Darken the OFF track; the checked rule is
     matched separately so the ON state keeps reading as green, not neutral. */
  #onetrust-pc-sdk .ot-switch .ot-switch-nob {
    background-color: #3d444d !important;
    border-color: #3d444d !important;
  }

  #onetrust-pc-sdk .ot-switch .ot-switch-nob:before {
    background-color: #c4cdd6 !important;
  }

  #onetrust-consent-sdk #onetrust-pc-sdk .ot-tgl input:checked + .ot-switch .ot-switch-nob {
    background-color: #3fb950 !important;
    border-color: #3fb950 !important;
  }

  #onetrust-pc-sdk #clear-filters-handler {
    color: #5fb0e6 !important;
  }

  /* Footer of the vendor-filter flyout. OneTrust hands both buttons SE's
     `--black-600` fill, so on the dark flyout Apply and Cancel become two
     edgeless blocks that also stop telling each other apart. */
  #onetrust-consent-sdk #onetrust-pc-sdk #filter-apply-handler {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  #onetrust-consent-sdk #onetrust-pc-sdk #filter-cancel-handler {
    background-color: transparent !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }

  /* Vendors List sub-screen ("List of partners (vendors)" in the banner, or the
     Vendors link inside the preference center). It is a SEPARATE view from the
     category list `#ot-pc-lst` above, with its own ids, so none of the rules
     above reach it. `#ot-sel-blk` is the "Allow All Consent" header row and is
     the only pure-white surface left anywhere in the theme; the ~265 vendor rows
     and the ~1300 purpose headings under an expanded vendor each draw an
     OneTrust light divider (#e2e2e2 / #e9e9e9). */
  #onetrust-pc-sdk #ot-sel-blk,
  #onetrust-pc-sdk #ot-lst-cnt,
  #onetrust-pc-sdk #ot-pc-lst .ot-sel-all,
  #onetrust-pc-sdk .ot-ven-dets {
    background-color: #20262d !important;
    border-color: #2d333b !important;
  }

  /* `.ot-ven-dets` only exists once a vendor row is EXPANDED, so a scan of the
     collapsed list reports it clean. OneTrust paints its value text near-black
     on every tag inside, so name the tags, not just the list items. */
  #onetrust-pc-sdk .ot-ven-dets li,
  #onetrust-pc-sdk .ot-ven-dets p,
  #onetrust-pc-sdk .ot-ven-dets h5,
  #onetrust-pc-sdk .ot-ven-dets span {
    color: #c4cdd6 !important;
  }

  #onetrust-pc-sdk #ot-sel-blk .ot-consent-hdr,
  #onetrust-pc-sdk #ot-sel-blk .ot-li-hdr,
  #onetrust-pc-sdk .ot-ven-hdr,
  #onetrust-pc-sdk .ot-ven-name {
    color: #e6edf3 !important;
  }

  #onetrust-pc-sdk #ot-ven-lst,
  #onetrust-pc-sdk li.ot-ven-item,
  #onetrust-pc-sdk .ot-ven-item .ot-acc-hdr,
  #onetrust-pc-sdk .ot-ven-pur h5,
  #onetrust-pc-sdk .ot-ven-dets,
  #onetrust-pc-sdk .ot-ven-dets li {
    border-color: #2d333b !important;
  }

  /* the round filter button keeps a #bbb ring (and a #555 glyph colour) around
     its brand-blue disc — a bright halo beside the dark search field */
  #onetrust-pc-sdk #filter-btn-handler {
    border-color: #3b82b8 !important;
    color: #ffffff !important;
  }

  /* preference-center close glyph */
  #onetrust-pc-sdk .ot-close-icon {
    filter: invert(1) brightness(0.9);
  }

  /* Keyboard focus ring. SE sets it to #2445b3, which reads 8:1 on OneTrust's
     white panel and under 2:1 on the darkened one — the ring survives but stops
     being visible. Mirror the 2-id selector it is stated at. */
  #onetrust-consent-sdk #onetrust-pc-sdk :focus,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-vlst-cntr > a:focus,
  #onetrust-consent-sdk #onetrust-banner-sdk :focus,
  #onetrust-consent-sdk #onetrust-banner-sdk:focus {
    outline-color: #5fb0e6 !important;
  }

  /* The banner is a fixed-height scrolling panel and OneTrust styles its own
     scrollbar: `::-webkit-scrollbar { width: 11px }` with a #c1c1c1 thumb and no
     track rule. On the darkened panel that thumb is a bright light bar running its
     full height — the single brightest thing on a first visit, and a scrollbar
     pseudo-element no element walk can reach. Mirror OneTrust's own
     id+class specificity so the override lands. `.ot-pc-scrollbar` is the
     class OneTrust puts on every inner scroller, including the vendor-filter
     flyout's fieldset, which has its own lighter #d8d8d8 thumb rule. */
  #onetrust-banner-sdk::-webkit-scrollbar,
  #onetrust-banner-sdk.otFloatingRoundedCorner::-webkit-scrollbar,
  #onetrust-pc-sdk::-webkit-scrollbar,
  #onetrust-pc-sdk #ot-pc-lst::-webkit-scrollbar,
  #onetrust-pc-sdk .ot-pc-scrollbar::-webkit-scrollbar {
    background-color: #14181d !important;
  }

  #onetrust-banner-sdk::-webkit-scrollbar-thumb,
  #onetrust-banner-sdk.otFloatingRoundedCorner::-webkit-scrollbar-thumb,
  #onetrust-pc-sdk::-webkit-scrollbar-thumb,
  #onetrust-pc-sdk #ot-pc-lst::-webkit-scrollbar-thumb,
  #onetrust-pc-sdk .ot-pc-scrollbar::-webkit-scrollbar-thumb {
    background: #3d444d !important;
  }

  /* The preference-center panel is `overflow: scroll` on BOTH axes, so both
     gutters are always drawn and they meet in a `::-webkit-scrollbar-corner`
     — a separate pseudo-element the track rule above does not cover, and one
     that defaults to solid WHITE. It renders as a bright 16px square welded to
     the bottom-right corner of the dialog. */
  #onetrust-banner-sdk::-webkit-scrollbar-corner,
  #onetrust-banner-sdk.otFloatingRoundedCorner::-webkit-scrollbar-corner,
  #onetrust-pc-sdk::-webkit-scrollbar-corner,
  #onetrust-pc-sdk #ot-pc-lst::-webkit-scrollbar-corner,
  #onetrust-pc-sdk .ot-pc-scrollbar::-webkit-scrollbar-corner {
    background-color: #14181d !important;
  }

  /* ============================================================
     Tables (in prose)
     ============================================================ */
  .s-prose table,
  .s-table {
    border-color: #2d333b !important;
  }

  .s-prose th, .s-table thead th {
    background-color: #20262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Row-header cells (<th scope="row">) — e.g. the "Search type"
     column of the /search "Advanced Search Tips" table (Tags, Exact,
     Author, Score…). These live in <tbody>, so the thead-th rule
     misses them: SE leaves them its near-black #0c0d0e (dark-on-dark)
     with light #d6d9dc row-divider borders. Lift the text and darken
     the borders without forcing the filled header bg. */
  .s-table tbody th,
  .s-table th[scope="row"] {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
    background-color: transparent !important;
  }

  .s-prose td, .s-table td,
  .s-table tbody th {
    border-color: #262c33 !important;
  }

  .s-prose td, .s-table td {
    color: #c4cdd6 !important;
  }

  .s-prose tr:nth-child(even) td {
    background-color: #181d23 !important;
  }

  /* ============================================================
     Post timeline (/posts/<id>/timeline)
     ------------------------------------------------------------
     Reached from the clock icon in every post's vote column, and
     anonymous. Its own stylesheet paints from raw Stacks tokens, so
     no utility remap reaches it.
     ============================================================ */
  /* A deleted event plates the row from `--red-100` on each <td>, not
     on the <tr> — the rule has to repeat per cell to cover the row. */
  .post-timeline tr.deleted-event td {
    background-color: #2a1718 !important;
  }

  .post-timeline tr.separator > td > div {
    background-color: #2d333b !important;
  }

  .post-timeline tr.separator > td > div.deleted {
    background-color: #5a2a2c !important;
  }

  /* Event kinds are `.event-type > span` pills, each filled by one raw
     token. `history` (--black-225) and `comment` (--black-350) are the
     two light-theme greys; every other kind is a brand hue that already
     reads on dark and must keep its own colour. `.comment` additionally
     collides with the post-comment component, whose network-wide
     transparent + divider rule outranks the site's pill fill. */
  .post-timeline .event-type > span.history {
    background-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .post-timeline .event-type > span.comment {
    background-color: #454e59 !important;
    color: #f0f4f8 !important;
    border: 0 !important;
  }

  /* ============================================================
     Badge detail page (/help/badges/<id>/<slug>)
     ============================================================ */
  /* Every awarded row is separated by a `--black-200` top rule and a
     page lists ~30 of them, so the light hairlines stripe the column. */
  .badges-page .single-badge-table .single-badge-row-question,
  .badges-page .single-badge-table .single-badge-row-reason {
    border-top-color: #262c33 !important;
  }

  /* ============================================================
     Editor (Markdown answer/comment box) — public on ask flow
     ============================================================ */
  .wmd-button-bar,
  .wmd-container,
  .js-editor-toolbar {
    background-color: #20262d !important;
    border-color: #2d333b !important;
  }

  /* The toolbar row draws the separator under the buttons from its own
     id rule, which the .wmd-button-bar border above cannot reach, and
     keeps it a light #babfc5 — a bright rule straight across the answer
     box. The guest answer form on the network sites renders the editor
     logged-out, so this is a public surface. */
  ul#wmd-button-row,
  .wmd-button-row {
    border-color: #2d333b !important;
  }

  /* The Markdown help strip and its "?" toggle only mount once the answer
     box takes focus, and the textarea sits on a resize grippie — all three
     are SE #f1f2f3 plates with #babfc5 rules, and the strip already carries
     our light tab labels, so it reads light-on-light until the plate moves.
     The grippie and the "?" glyph are both drawn from the legacy sprite:
     the "?" lives alone in its own <span> so it can be inverted, the
     grippie paints its dots on the same box as the plate and can only drop
     them. */
  button#wmd-help-button,
  div#mdhelp,
  ul#mdhelp-tabs,
  .grippie {
    background-color: #20262d !important;
    border-color: #2d333b !important;
  }

  .grippie {
    background-image: none !important;
  }

  button#wmd-help-button > span {
    filter: invert(1) !important;
  }

  .wmd-preview {
    background-color: #181d23 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* /collectives ships its own in-page <style> for the section nav that
     scroll-spies the marketing blocks: `.p-collectives-nav { background:
     rgba(250,250,251,.8); backdrop-filter: blur(10px) }`. It is `ps-sticky`
     under the topbar, so it rides the whole page as a full-width near-white
     band. The sheet's `body.theme-dark` arm never applies — anonymous
     visitors are on `unified-theme`. Kill the blur too: over a dark page it
     only smears the content scrolling under the bar. */
  .p-collectives-nav,
  nav#feature-nav {
    background: #1c2128 !important;
    backdrop-filter: none !important;
  }

  /* ============================================================
     Misc light leftovers
     ============================================================ */
  .bc-black-025, .bc-black-050, .bc-black-075,
  .bc-black-100, .bc-black-150, .bc-black-200,
  .bc-black-300, .bc-black-400, .bc-powder-300,
  .ba, .bb, .bt, .bl, .br,
  .s-btn-group,
  .flush-left, .snippet-hidden,
  select, .s-select, .s-select select,
  .s-sidebarwidget--item, .s-sidebarwidget__item,
  .s-card.bc-black-100 {
    border-color: #262c33 !important;
  }

  /* A Stacks tab strip encodes its current tab in the border-colour utility —
     `bc-black-600` on the selected item, `bc-transparent` on the rest — so the
     bare `.bb` arm above paints both the same rule and the indicator vanishes
     (the network home's Questions/Sites/Moderators strip). Scoped to the
     navigation component: elsewhere `bc-transparent` can be a hover hook. */
  .s-navigation--item.bc-transparent {
    border-color: transparent !important;
  }

  .s-navigation--item.bc-black-600 {
    border-color: #e6edf3 !important;
  }

  /* Stacks gives EVERY `.s-btn` a `1px solid transparent` border for layout, so
     a border-colour hook only belongs on variants that natively show one.
     `__outlined` is the only such variant: `__muted`, `__filled` and the width
     utility `.w100` all keep the border transparent, and colouring them draws a
     box the site never draws (the topbar search trigger beside two bare icon
     buttons, the modal close X, the white Google pill). */
  .s-btn__outlined {
    border-color: #2d333b !important;
  }

  .bg-black-025, .bg-black-050, .bg-black-075,
  .bg-black-100, .bg-black-150, .bg-black-200,
  .bg-powder-100, .bg-powder-200, .bg-powder-300 {
    background-color: #1c2128 !important;
  }

  /* ---- Pagination ------------------------------------------- */
  .s-pagination--item,
  a.s-pagination--item,
  .s-pagination .s-pagination--item {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .s-pagination--item:hover {
    background-color: #222831 !important;
    color: #e6edf3 !important;
  }

  .s-pagination--item.is-selected,
  span.s-pagination--item.is-selected {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  hr, .s-prose hr { border-color: #262c33 !important; }

  /* "hot" question orange flame indicator: brighten for contrast */
  .hot, .fc-orange-500.hot, span.hot {
    color: #e0913f !important;
  }

  /* Top promo / dismissable announcement banner (blue) -> dark
     so its body text is readable; keep a subtle blue accent. */
  .s-banner,
  .js-dismissable-hero,
  .s-banner__container,
  #announcement-banner,
  .js-announcement-banner,
  .bg-blue-400, .bg-blue-500, .bg-blue-600,
  .top-banner {
    background-color: #14222e !important;
    color: #cfe0ef !important;
    border-color: #234055 !important;
  }

  #announcement-banner.fc-white,
  #announcement-banner a,
  .s-banner a,
  .s-banner .s-link,
  .js-dismissable-hero a {
    color: #cfe0ef !important;
  }

  /* `.bg-blue-500` is not only the banner tint: Stacks also stamps it on SOLID
     controls, where the retone above flattens a brand fill to a near-black
     plate. The network home carries two — its "Take a tour" CTA and the
     selected pill of the Hot/Real-time strip, which then reads as unselected. */
  a.s-navigation--item.bg-blue-500,
  .s-navigation--item.bg-blue-500 {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  a.s-navigation--item.bg-blue-500:hover,
  .s-navigation--item.bg-blue-500:hover {
    background-color: #3b82b8 !important;
    color: #ffffff !important;
  }

  /* tinted info / callout boxes (purple / green / yellow / red
     pastel backgrounds used for "you can also…", new-contributor
     notices, etc.) -> tinted dark with readable text. */
  .bg-purple-100, .bg-purple-200 {
    background-color: #221c2e !important;
    border-color: #3a2f55 !important;
    color: #d7c9ef !important;
  }

  .bg-green-100, .bg-green-200 {
    background-color: #16221a !important;
    border-color: #25402d !important;
    color: #aee0bb !important;
  }

  .bg-yellow-100, .bg-yellow-200 {
    background-color: #221d14 !important;
    border-color: #3a3320 !important;
    color: #e8d4a0 !important;
  }

  .bg-red-100, .bg-red-200 {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0bcbc !important;
  }

  /* Light-blue info tint (#edf5fd). Used to highlight the SELECTED
     revision row on a post's /revisions page and other light-blue
     "info" callouts — a glaring near-white blue panel on dark. Its
     blue-channel (253) sneaks under some near-white thresholds but
     the surface reads bright. Retone to the same tinted-dark-blue as
     the .s-notice__info panels. */
  .bg-blue-100, .bg-blue-200 {
    background-color: #14222e !important;
    border-color: #234055 !important;
    color: #cfe0ef !important;
  }

  /* `.bg-blue-300` (#92c2f2) is the step between them and the banner tint, and
     it was the only one left native: /collectives builds its explainer mock's
     tag chips from it, eight solid pastel bars on the dark card. It is not
     near-WHITE, so the light-surface scan (all channels > 200) never sees it —
     only a luminance read does. Keep it recognisably blue, one step up from the
     banner fill. */
  .bg-blue-300 {
    background-color: #234055 !important;
  }

  /* Post /revisions diff highlights. SE marks changed text with light-theme
     highlighter fills — `span.diff-add` green-300 #94ccae on green-600 text,
     `span.diff-delete` red-300 #eeaaaa on red-600 — the biggest bright
     surfaces anywhere in the theme, and a bg-COLOR audit misses them because
     the red channel (148 / 238) straddles the near-white threshold. The
     whole family needs the same treatment, not just the two inline spans:
     the side-by-side view paints WHOLE LINES from `.full-diff .inserted>div`
     / `.deleted>div`, its `.skip` marker is a black-150 band framed by 4px
     WHITE borders, and its `td.content` body text is black-350 (3.5:1 once
     the page is dark). Retone to saturated-dark tints that still read as
     highlighter marks. */
  span.diff-add,
  .diff-add {
    background-color: #1c4229 !important;
    color: #c7f0d3 !important;
  }

  span.diff-delete,
  .diff-delete {
    background-color: #4a1d20 !important;
    color: #f6c8c8 !important;
  }

  .full-diff .inserted > div {
    background-color: #16221a !important;
  }

  .full-diff .deleted > div {
    background-color: #2a1718 !important;
  }

  .full-diff .skip {
    background-color: #20262d !important;
    color: #9198a1 !important;
    border-top-color: #262c33 !important;
    border-bottom-color: #262c33 !important;
  }

  .full-diff td.content,
  .full-html-diff th,
  .suggested-edit .body-diffs .full-html-diff th {
    color: #c4cdd6 !important;
  }

  /* Diff "skipped lines" separator on /revisions (inline diff view):
     SE draws the collapsed-region marker as a 2px light #c4cdd6
     border-bottom on a full-width strip — a glaring bright horizontal
     rule on dark. Recolor to a subtle dark divider. */
  .diff-skipped,
  .diff-skipped > div,
  .s-prose .diff-skipped > div {
    border-color: #2d333b !important;
  }

  /* Post /revisions header meta links ("Source" / "Link" toggles):
     bare <a class="flex--item"> inheriting SE's near-black #636b74 —
     dark-on-dark on the (now dark) revision header panel. The base
     `a` rule is unimportant so SE's inherited color wins; lift these
     scoped links to a legible accent. */
  .js-revision .d-flex a.flex--item,
  .js-revision .d-flex a.flex--item:visited {
    color: #5fb0e6 !important;
  }

  .bc-purple-400 { border-color: #3a2f55 !important; }

  /* light channel chips / teams pills (#f1f2f3 leftover).
     NOTE: the left-nav label spans also carry .-link--channel-name
     but must stay transparent at rest — they are re-neutralized in
     the Left navigation sidebar section, which uses a higher-
     specificity selector (.nav-links--link .-link--channel-name) so
     this broad rule does not chip them. */
  .ml4.bg-black-150,
  .s-badge.bg-black-150 {
    background-color: #222831 !important;
    color: #c4cdd6 !important;
  }

  /* footer extra row light border */
  .site-footer--extra, .site-footer--menu {
    border-color: #262c33 !important;
  }

  /* sidebar widget item rows (.ba light border leftover) */
  .s-sidebarwidget--content.s-sidebarwidget__item,
  .s-sidebarwidget--content.s-sidebarwidget__items,
  .s-sidebarwidget__items,
  .s-sidebarwidget__item.s-sidebarwidget--content {
    border-color: #2d333b !important;
  }

  /* muted button text label (Users page sort buttons etc.) */
  .s-btn--text, .s-btn .s-btn--text {
    color: #c4cdd6 !important;
  }

  /* Hide blank ad slots so they don't leak white frames. `.js-ad-zone` is
     unconditional: a FILLED zone is covered by its own iframe, so a transparent
     parent is invisible there. The previous iframe-presence guard used a relational
     selector, which sanitization strips from .org.css — so userstyles.org never
     received that arm at all. (Measured 2026-07-10: `.js-ad-zone` currently matches
     0 elements on a live question page; `.js-zone-container` and
     `.everyonelovesstackoverflow` are natively transparent and 0px tall. This rule
     is defensive, not load-bearing.) */
  .js-zone-container,
  .js-ad-zone,
  .everyonelovesstackoverflow,
  .js-report-ad {
    background-color: transparent !important;
  }

  /* The in-comments "native" ad row (`li.comment.native-comment-ad`) draws its own
     1px #f1f2f3 bottom rule on the INNER `.js-zone-container`, not on the `.comment`
     our divider rule targets — a bright white line straight across the comment list.
     A filled creative hides it; an unfilled or blocked slot leaves just the line. */
  .js-zone-container,
  .zone-container-native-comment,
  .comment.native-comment-ad,
  .comment.native-comment-ad .js-zone-container {
    border-color: #262c33 !important;
  }

  /* The MOBILE sticky bottom anchor ad (Aditude) wraps its slot in a hard
     #fff container pinned across the foot of the viewport. A creative that
     fills it hides the white; an unfilled, transparent or narrower one leaves
     a white band glued to the bottom of every page. Desktop review never sees
     it — the slot only mounts below the `md` breakpoint. It is a floating
     surface, so give it a solid dark fill rather than transparent. */
  #pb-anchor--wrapper,
  #pb-anchor--wrapper-inner,
  .tude-anchor-wrapper-outer,
  .tude-anchor-wrapper-inner {
    background-color: #14181d !important;
  }

  /* "Report this ad" chrome pill on the sticky anchor ad renders a
     light #f0f0f0 background with near-invisible light-grey text —
     a glaring light pill on dark. Darken it + lift the label. */
  .mobile-anchor-ad-report-button-container,
  .js-report-ad-button-container {
    background-color: #1c2128 !important;
  }
  .mobile-anchor-ad-report-button-container .js-report-ad,
  .js-report-ad-button-container .js-report-ad,
  .mobile-anchor-ad-report-button {
    color: #9198a1 !important;
  }

  /* The "AD" disclosure the site's own ad loader stamps over a slot that
     rendered an Acceptable Ad (list rows, the sidebar slots, the bottom
     anchor). It is an unclassed div styled through `el.style`, so the only
     hook is the serialised attribute: the CSSOM writes `rgba(255, 255, 255,
     0.7)` WITH spaces, and the unspaced arm covers the same value set as
     attribute text. It must stay a legible disclosure over whatever
     creative sits under it, so only the plate and ink move. */
  .js-zone-container div[style*="rgba(255, 255, 255, 0.7)"],
  .js-zone-container div[style*="rgba(255,255,255,0.7)"],
  .everyonelovesstackoverflow div[style*="rgba(255, 255, 255, 0.7)"],
  .everyonelovesstackoverflow div[style*="rgba(255,255,255,0.7)"],
  .aditude-div-wrapper div[style*="rgba(255, 255, 255, 0.7)"],
  .aditude-div-wrapper div[style*="rgba(255,255,255,0.7)"] {
    background-color: rgba(20, 24, 29, 0.85) !important;
    color: #c4cdd6 !important;
  }

  /* keep images untouched (no filter/recolor) */
  .s-prose img, img { /* intentionally no override */ }
}

